select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'MACHINERY' AND o_orderdate = '1993-05-19' AND o_custkey < 5332 AND o_orderkey < 1137538
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#13'  and p_container = 'LG DRUM'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'CANADA' and n2.n_name = 'CHINA')     or (n1.n_name = 'CHINA' and n2.n_name = 'CANADA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
SELECT p_type, s_phone, ps_comment, AVG(s_suppkey), MIN(ps_comment) FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey WHERE s_comment < 's. carefully unusual foxes according to the express realms hagg' AND ps_partkey >= 55775 AND ps_supplycost = 622.91 GROUP BY p_type, s_phone, ps_comment ORDER BY ps_comment DESC, s_phone ASC
