SELECT p_size, ps_supplycost, COUNT(ps_suppkey) FROM part JOIN partsupp ON ps_partkey = p_partkey WHERE ps_availqty >= 9934 AND p_comment > 'depos' AND p_container > 'SM CAN' GROUP BY p_size, ps_supplycost HAVING COUNT(ps_suppkey) = 1229 ORDER BY COUNT(ps_suppkey) ASC
SELECT l_orderkey, ps_availqty FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_orderkey < 189383 AND l_tax >= 0.08 AND ps_partkey > 83788 AND l_linestatus > 'O' ORDER BY l_orderkey DESC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('20', '19', '31', '11', '14', '18', '26')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('20', '19', '31', '11', '14', '18', '26')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'JORDAN' and n2.n_name = 'PERU')     or (n1.n_name = 'PERU' and n2.n_name = 'JORDAN')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select s_comment, ps_partkey, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000001926' AND l_partkey > 92630 group by s_comment, ps_partkey, l_shipmode having min(s_name) <= 'Supplier#000003746' order by sum(ps_partkey) DESC, min(s_name) ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#25'  and p_type not like 'MEDIUM POLISHED%'  and p_size in (27, 25, 19, 50, 24, 16, 3, 13)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT o_shippriority, l_returnflag FROM lineitem, orders WHERE l_shipmode <= 'AIR' AND o_orderpriority >= '5-LOW' AND l_linestatus < 'O' AND l_orderkey = 1490758 AND o_orderstatus > 'O' AND l_returnflag >= 'A'
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where p_brand > 'Brand#25' AND ps_supplycost > 650.88 AND l_returnflag = 'A' AND l_linenumber = 7 order by p_mfgr DESC, l_linenumber ASC
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1997-01-01'  and l_shipdate < date '1997-01-01' + interval '1' year  and l_discount between 0.05 - 0.01 and 0.05 + 0.01  and l_quantity < 25 ;
select o_totalprice, o_orderstatus from lineitem, orders where o_totalprice >= 68621.84 AND l_extendedprice = 27980.8 AND l_linestatus = 'F' AND l_suppkey = 7283
select p_partkey, ps_comment, l_partkey from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where p_size > 12 AND ps_comment = 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND l_shipmode = 'SHIP' AND p_retailprice <= 1831.73
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#21'  and p_type not like 'ECONOMY ANODIZED%'  and p_size in (13, 49, 26, 41, 5, 6, 44, 12)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#13'  and p_type not like 'PROMO BRUSHED%'  and p_size in (35, 32, 13, 19, 8, 23, 44, 17)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT l_linenumber, o_shippriority, MIN(l_receiptdate) FROM orders JOIN lineitem ON l_orderkey = o_orderkey WHERE l_tax <> 0.01 AND l_returnflag = 'R' AND l_extendedprice <= 2000.99 GROUP BY l_linenumber, o_shippriority ORDER BY l_linenumber ASC, o_shippriority ASC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'IRAN' and n2.n_name = 'KENYA')     or (n1.n_name = 'KENYA' and n2.n_name = 'IRAN')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#53'  and p_container = 'LG JAR'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT ps_suppkey, l_orderkey FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_orderkey >= 1666785 AND l_commitdate = '1995-12-06' AND l_shipdate <> '1995-10-29' AND l_receiptdate < '1992-06-09' AND ps_partkey > 71581 ORDER BY ps_suppkey ASC, l_orderkey ASC
select ps_comment, s_name, p_mfgr, r_comment, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where r_name < 'MIDDLE EAST' AND ps_availqty = 8560 AND n_comment = 'platelets. blithely pending dependencies use fluffily across the even pinto beans. carefully silent accoun'
SELECT o_comment, c_address FROM orders, customer WHERE c_acctbal >= 1083.06 AND o_shippriority < 0 AND o_totalprice >= 30920.17 AND o_orderpriority >= '2-HIGH' ORDER BY o_comment DESC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#15'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 9 and l_quantity <= 9 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#54'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 15 and l_quantity <= 15 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#14'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 24 and l_quantity <= 24 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'MACHINERY'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-14'  and l_shipdate > date '1995-03-14' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  o_year,  sum(case   when nation = 'UNITED KINGDOM' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL PLATED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'CHINA' and n2.n_name = 'BRAZIL')     or (n1.n_name = 'BRAZIL' and n2.n_name = 'CHINA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#15'  and p_type not like 'SMALL PLATED%'  and p_size in (45, 14, 4, 27, 41, 44, 2, 6)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'FRANCE' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'FRANCE'   ) order by  value desc ;
SELECT c_address, o_shippriority FROM orders JOIN customer ON c_custkey = o_custkey WHERE c_name > 'Customer#000014181' AND c_mktsegment <> 'FURNITURE' AND o_clerk = 'Clerk#000000072' AND o_totalprice <> 44719.4
select s_comment, ps_partkey, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000009797' AND l_partkey > 63858 group by s_comment, ps_partkey, l_shipmode having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment > 'HOUSEHOLD' AND o_orderpriority >= '5-LOW' AND o_custkey < 9136 AND o_orderkey < 2232065
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#43'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 5 and l_quantity <= 5 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#33'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 13 and l_quantity <= 13 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#54'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 29 and l_quantity <= 29 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select l_receiptdate, o_totalprice from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 260497.06 AND o_custkey > 101332 AND l_tax > 0.07 order by o_totalprice DESC, l_receiptdate ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#11'  and p_type not like 'SMALL BURNISHED%'  and p_size in (31, 2, 26, 10, 20, 19, 35, 16)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT o_orderdate, l_linenumber, ps_comment FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_shipinstruct > 'DELIVER IN PERSON' AND l_discount < 0.02 AND l_partkey > 63858 AND o_shippriority < 0 ORDER BY ps_comment DESC
select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'O' AND p_type = 'STANDARD BRUSHED STEEL' AND l_commitdate = '1996-01-02' AND l_orderkey < 2618950 AND ps_comment > 'l theodolites across the slyly unusual accounts wake carefully pending accounts' order by ps_partkey DESC, p_name ASC
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#41'  and p_container = 'WRAP CAN'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT ps_supplycost FROM partsupp WHERE ps_comment <> 'ide of the even, ironic instructions nag above the bo' AND ps_suppkey <= 2395 AND ps_supplycost < 490.08 AND ps_availqty <> 7752 ORDER BY ps_supplycost ASC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'ARGENTINA' and n2.n_name = 'BRAZIL')     or (n1.n_name = 'BRAZIL' and n2.n_name = 'ARGENTINA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select s_comment, ps_partkey, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000001275' AND l_partkey > 18720 group by s_comment, ps_partkey, l_shipmode having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
SELECT ps_availqty, l_linenumber FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_commitdate = '1996-11-03' AND l_extendedprice >= 55105.5 AND l_returnflag >= 'N' AND l_shipmode <> 'SHIP'
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'peru%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1993-01-01'      and l_shipdate < date '1993-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'CANADA' order by  s_name ;
select ps_partkey, ps_availqty, n_comment from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey where n_regionkey < 1 AND ps_suppkey >= 6121 AND ps_availqty >= 3514 order by ps_availqty ASC
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'MACHINERY'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-18'  and l_shipdate > date '1995-03-18' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select l_comment, l_quantity, s_address from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct <= 'DELIVER IN PERSON' AND s_phone = '27-403-707-5612' AND s_suppkey = 1933 order by s_address DESC, l_quantity ASC
select p_mfgr, ps_availqty, min(p_mfgr) from part JOIN partsupp ON ps_partkey = p_partkey where ps_partkey = 139827 AND ps_availqty = 5532 AND p_container <= 'SM BAG' group by p_mfgr, ps_availqty having min(p_mfgr) = 'Manufacturer#1'
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('FOB', 'SHIP')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1993-01-01'  and l_receiptdate < date '1993-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('26', '17', '20', '25', '10', '18', '30')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('26', '17', '20', '25', '10', '18', '30')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT p_brand, l_shipmode, ps_suppkey FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE ps_comment <> 'ggle slyly requests. furiously express packages cajole slyly. even instructions above the carefully e' AND ps_suppkey < 3039 AND p_retailprice = 1467.54 AND p_size < 48 ORDER BY l_shipmode ASC
select p_brand, ps_availqty, min(ps_availqty) from part JOIN partsupp ON ps_partkey = p_partkey where p_size = 12 AND p_mfgr = 'Manufacturer#2' AND ps_partkey <= 180166 group by p_brand, ps_availqty having min(ps_availqty) = 1678
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1996-01-01'  and o_orderdate < date '1996-01-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select p_mfgr, ps_availqty, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 6827 AND p_mfgr = 'Manufacturer#5' AND ps_partkey <= 173618 group by p_mfgr, ps_availqty having min(p_container) = 'WRAP DRUM'
SELECT o_orderpriority, c_nationkey FROM orders, customer WHERE c_acctbal = 1481.44 AND c_mktsegment <> 'HOUSEHOLD' AND o_comment <= 'ironic, bold requests wake slyly' AND c_phone = '20-713-568-2804'
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'R' AND p_brand > 'Brand#23' AND ps_supplycost = 893.31 AND l_linenumber = 3 order by p_mfgr DESC, l_linenumber ASC
select  c_custkey,  c_name,  sum(l_extendedprice * (1 - l_discount)) as revenue,  c_acctbal,  n_name,  c_address,  c_phone,  c_comment from  customer,  orders,  lineitem,  nation where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate >= date '1994-04-01'  and o_orderdate < date '1994-04-01' + interval '3' month  and l_returnflag = 'R'  and c_nationkey = n_nationkey group by  c_custkey,  c_name,  c_acctbal,  c_phone,  n_name,  c_address,  c_comment order by  revenue desc limit 20;
select ps_suppkey, s_comment, r_regionkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 10 AND ps_suppkey >= 6999 group by ps_suppkey, s_comment, r_regionkey, n_regionkey order by ps_suppkey DESC, r_regionkey DESC
SELECT c_address, o_clerk FROM orders JOIN customer ON c_custkey = o_custkey WHERE c_nationkey = 19 AND o_comment <= 'the unusual, pending shea' AND o_orderdate = '1997-08-21' AND c_name < 'Customer#000070744' ORDER BY o_clerk ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#44'  and p_type not like 'PROMO BURNISHED%'  and p_size in (44, 4, 11, 16, 12, 9, 3, 43)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select l_shipinstruct, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 120307 AND ps_comment = 'sts along the pending pinto beans affix quietly about the fluffily final pinto beans. special, bold requests may sleep slyly special requests. pinto beans sleep. deposits breach. quickly re' AND l_shipmode = 'SHIP' AND p_retailprice <= 1312.23
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#43'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 8 and l_quantity <= 8 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 18 and l_quantity <= 18 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#15'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 26 and l_quantity <= 26 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT s_address, l_quantity, ps_suppkey FROM lineitem, partsupp, supplier WHERE l_orderkey >= 5367938 AND l_comment = 'ular escap' AND s_phone = '24-810-371-6779' AND s_suppkey >= 8612 AND l_extendedprice = 6394.08
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'BRAZIL' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'BRAZIL'   ) order by  value desc ;
select ps_suppkey, s_comment, r_regionkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 5975 group by ps_suppkey, s_comment, r_regionkey, n_regionkey order by ps_suppkey DESC, r_regionkey DESC
select p_container, ps_availqty, min(ps_partkey) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 5816 AND p_mfgr = 'Manufacturer#4' AND p_mfgr <= 'Manufacturer#4' group by ps_availqty, p_container having min(ps_partkey) = 57823
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('29', '21', '19', '23', '22', '18', '13')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('29', '21', '19', '23', '22', '18', '13')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select ps_comment, p_name, l_commitdate from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_orderkey = 4853414 AND p_type = 'STANDARD BRUSHED STEEL' AND ps_partkey = 27306 AND l_orderkey < 2618950 AND l_linestatus > 'F' order by ps_comment DESC, p_name ASC
select  s_name,  count(*) as numwait from  supplier,  lineitem l1,  orders,  nation where  s_suppkey = l1.l_suppkey  and o_orderkey = l1.l_orderkey  and o_orderstatus = 'F'  and l1.l_receiptdate > l1.l_commitdate  and exists (   select    *   from    lineitem l2   where    l2.l_orderkey = l1.l_orderkey    and l2.l_suppkey <> l1.l_suppkey  )  and not exists (   select    *   from    lineitem l3   where    l3.l_orderkey = l1.l_orderkey    and l3.l_suppkey <> l1.l_suppkey    and l3.l_receiptdate > l3.l_commitdate  )  and s_nationkey = n_nationkey  and n_name = 'CHINA' group by  s_name order by  numwait desc,  s_name limit 100;
select  o_year,  sum(case   when nation = 'ROMANIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO BURNISHED TIN'  ) as all_nations group by  o_year order by  o_year ;
select s_address, s_comment, r_regionkey, ps_comment, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_acctbal > 4975.09 AND s_acctbal >= 2543.89 group by r_regionkey, s_comment, ps_comment, s_address order by r_regionkey DESC, ps_comment DESC
select c_nationkey, o_orderstatus, n_comment from orders, customer, nation where o_totalprice < 36447.99 AND c_acctbal = 1481.44 AND c_name = 'Customer#000143733' AND c_mktsegment > 'BUILDING' AND o_shippriority < 0
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#12'  and p_type not like 'LARGE BURNISHED%'  and p_size in (17, 46, 40, 6, 44, 16, 15, 49)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT l_shipmode, o_shippriority FROM orders JOIN lineitem ON l_orderkey = o_orderkey WHERE l_shipinstruct <> 'DELIVER IN PERSON' AND l_partkey = 9605 AND l_linenumber <= 6 AND o_totalprice < 85142.36 ORDER BY o_shippriority DESC, l_shipmode DESC
