SELECT o_clerk FROM orders WHERE o_orderstatus = 'F' AND o_orderpriority >= '5-LOW' AND o_orderdate <> '1995-11-01' AND o_comment < 'blithely. carefully bold theodolites integrate carefully amon' AND o_custkey <= 117772
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('SHIP', 'MAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT l_shipdate, c_phone, o_clerk, COUNT(l_partkey) FROM lineitem JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE o_comment <= 'al packages breach carefully quickly final packages. slyly' AND l_commitdate >= '1994-03-23' AND o_clerk <= 'Clerk#000000898' GROUP BY l_shipdate, c_phone, o_clerk ORDER BY COUNT(l_partkey) DESC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 16  and p_type like '%COPPER'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('33', '22', '26', '12', '14', '11', '18')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('33', '22', '26', '12', '14', '11', '18')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '86' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1995-02-01'  and l_shipdate < date '1995-02-01' + interval '1' month ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%cyan%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'N' AND p_brand > 'Brand#23' AND ps_supplycost = 797.15 AND l_linenumber = 7 order by p_mfgr DESC, l_linenumber ASC
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1997-01-01'  and l_shipdate < date '1997-01-01' + interval '1' year  and l_discount between 0.09 - 0.01 and 0.09 + 0.01  and l_quantity < 25 ;
select l_commitdate, ps_availqty from lineitem, partsupp where l_linestatus = 'O' AND l_orderkey < 458211 AND l_tax < 0.07 AND l_extendedprice = 41364.0
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'FURNITURE'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-20'  and l_shipdate > date '1995-03-20' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select o_totalprice, c_mktsegment from customer JOIN orders ON o_custkey = c_custkey where o_orderdate < '1993-08-21' AND c_comment = 'blithely pending ideas. foxes about the' AND o_custkey < 9136 AND o_orderkey < 3130309
select l_comment, s_phone, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'TAKE BACK RETURN' AND s_comment < 'nal instructions. regular courts haggle carefully a' AND s_suppkey = 1933 order by ps_partkey DESC, s_phone ASC
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%hot%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
