select c_nationkey, o_custkey, o_orderdate, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000146510' AND o_comment < 'ses above the packages sleep carefully pint' AND n_regionkey = 3 order by c_nationkey ASC, r_name DESC, o_custkey ASC
