select ps_availqty, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1998-04-15' AND l_partkey = 141608 AND l_returnflag >= 'N' AND l_shipinstruct = 'TAKE BACK RETURN'
select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'O' AND p_type = 'STANDARD BRUSHED STEEL' AND l_commitdate = '1998-01-07' AND l_orderkey < 5092134 AND ps_comment > 'sh. furiously special deposits nod fluffily. even deposits boost after the quickly ironic ideas. furiou' order by ps_partkey DESC, p_name ASC
select l_shipmode, l_returnflag, l_commitdate from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where l_commitdate > '1995-09-11' AND l_partkey = 141608 AND l_returnflag >= 'N' AND l_shipinstruct = 'NONE'
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 24  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select s_comment, ps_partkey, s_phone, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where l_partkey = 57835 AND s_name < 'Supplier#000001926' AND l_shipmode > 'TRUCK' group by s_comment, ps_partkey, s_phone having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select  c_custkey,  c_name,  sum(l_extendedprice * (1 - l_discount)) as revenue,  c_acctbal,  n_name,  c_address,  c_phone,  c_comment from  customer,  orders,  lineitem,  nation where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate >= date '1993-02-01'  and o_orderdate < date '1993-02-01' + interval '3' month  and l_returnflag = 'R'  and c_nationkey = n_nationkey group by  c_custkey,  c_name,  c_acctbal,  c_phone,  n_name,  c_address,  c_comment order by  revenue desc limit 20;
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1996-04-01'  and o_orderdate < date '1996-04-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select l_extendedprice, l_linestatus from lineitem, partsupp where l_commitdate = '1998-06-20' AND l_orderkey < 1666785 AND l_tax < 0.07 AND ps_availqty = 1404
select  o_year,  sum(case   when nation = 'IRAQ' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL PLATED BRASS'  ) as all_nations group by  o_year order by  o_year ;
SELECT ps_suppkey, l_shipinstruct, r_name, n_regionkey, s_acctbal FROM region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE ps_availqty <= 4749 AND r_regionkey < 4 AND s_acctbal = 1845.54
select s_nationkey, s_comment, ps_suppkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where r_regionkey > 4 AND ps_suppkey >= 6478 group by ps_suppkey, s_comment, s_nationkey, n_regionkey order by ps_suppkey DESC, s_nationkey DESC
select  c_count,  count(*) as custdist from  (   select    c_custkey,    count(o_orderkey)   from    customer left outer join orders on     c_custkey = o_custkey     and o_comment not like '%express%deposits%'   group by    c_custkey  ) as c_orders (c_custkey, c_count) group by  c_count order by  custdist desc,  c_count desc ;
SELECT c_phone, n_regionkey FROM customer, nation WHERE n_nationkey <> 24 AND n_comment <> 'ic deposits are blithely about the carefully regular pa' AND c_acctbal > -870.54 AND c_phone <> '31-508-135-3622' ORDER BY c_phone ASC
select l_commitdate, l_suppkey from lineitem, partsupp where l_comment = 'nusual accounts' AND l_quantity < 25.0 AND l_tax < 0.07 AND l_extendedprice = 41364.0
select l_comment, s_suppkey, l_shipinstruct from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where s_name = 'Supplier#000008916' AND s_name = 'Supplier#000005069' AND ps_partkey = 83788 order by l_shipinstruct DESC, s_suppkey ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 22  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT o_orderdate, s_comment, ps_suppkey, l_quantity, c_nationkey FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE o_clerk = 'Clerk#000000058' AND ps_availqty >= 4781 ORDER BY l_quantity ASC, ps_suppkey DESC
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%medium%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
SELECT l_linestatus, ps_suppkey, s_name FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey WHERE l_tax <> 0.03 AND s_nationkey = 5 AND s_comment <= 'al excuses. carefully permanent asymptotes haggle.' ORDER BY s_name ASC, ps_suppkey DESC, l_linestatus ASC
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1996-04-01'  and l_shipdate < date '1996-04-01' + interval '1' month ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('12', '34', '24', '19', '28', '11', '17')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('12', '34', '24', '19', '28', '11', '17')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT l_tax, s_suppkey, ps_supplycost FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_partkey < 27458 AND s_comment <= 'fluffily. bold instructions thrash' AND l_orderkey <= 119140 ORDER BY l_tax ASC, s_suppkey DESC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'PERU' and n2.n_name = 'RUSSIA')     or (n1.n_name = 'RUSSIA' and n2.n_name = 'PERU')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#25'  and p_container = 'WRAP CAN'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT p_type, ps_suppkey FROM partsupp, part WHERE p_mfgr < 'Manufacturer#2' AND p_size < 25 AND p_retailprice >= 1707.61 AND ps_availqty = 7011 ORDER BY p_type DESC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#12'  and p_type not like 'ECONOMY BURNISHED%'  and p_size in (39, 12, 30, 42, 41, 16, 43, 4)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 45  and p_type like '%STEEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
