select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#51'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 9 and l_quantity <= 9 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#34'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 13 and l_quantity <= 13 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 21 and l_quantity <= 21 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#11'  and p_type not like 'STANDARD BRUSHED%'  and p_size in (11, 14, 5, 40, 41, 30, 32, 19)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#33'  and p_container = 'LG DRUM'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'N' AND p_brand > 'Brand#31' AND ps_supplycost = 892.65 AND l_linenumber = 7 order by p_mfgr DESC, l_linenumber ASC
SELECT l_receiptdate, c_custkey, n_comment, o_shippriority FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE c_nationkey >= 21 AND l_receiptdate > '1997-02-10' AND l_orderkey > 3225285 AND l_shipmode < 'REG AIR' AND o_clerk < 'Clerk#000000551' ORDER BY n_comment DESC
SELECT ps_availqty, l_receiptdate, p_mfgr FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE l_shipdate < '1994-07-10' AND l_returnflag > 'N' AND p_partkey > 199323 AND ps_partkey <> 152695 AND ps_availqty > 439 ORDER BY l_receiptdate DESC, p_mfgr ASC
SELECT ps_partkey, p_mfgr FROM part JOIN partsupp ON ps_partkey = p_partkey WHERE p_size > 44 AND p_mfgr > 'Manufacturer#1' AND p_container <> 'SM CAN' AND p_brand <> 'Brand#35' AND p_type <> 'SMALL BURNISHED NICKEL'
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'green%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1997-01-01'      and l_shipdate < date '1997-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'VIETNAM' order by  s_name ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%sienna%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'royal%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1997-01-01'      and l_shipdate < date '1997-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'EGYPT' order by  s_name ;
select l_receiptdate, o_totalprice from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 239290.86 AND o_custkey > 71746 AND l_tax > 0.02 order by o_totalprice DESC, l_receiptdate ASC
select  o_year,  sum(case   when nation = 'EGYPT' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'ECONOMY ANODIZED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'MACHINERY'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-31'  and l_shipdate > date '1995-03-31' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#43'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 7 and l_quantity <= 7 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#42'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 20 and l_quantity <= 20 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#23'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 20 and l_quantity <= 20 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select s_nationkey, ps_partkey from partsupp JOIN supplier ON s_suppkey = ps_suppkey where s_nationkey >= 21 AND s_comment < 'ic requests nag. blithely regular ideas try to wake quickly eve' AND ps_availqty <= 5532 AND s_acctbal < 7888.41 AND ps_supplycost > 169.47 AND ps_supplycost <= 91.11
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1994-01-01'  and l_shipdate < date '1994-01-01' + interval '1' year  and l_discount between 0.02 - 0.01 and 0.02 + 0.01  and l_quantity < 24 ;
SELECT ps_partkey, l_shipdate FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_commitdate = '1993-01-21' AND l_extendedprice >= 10793.22 AND l_shipdate <> '1997-11-01' AND ps_suppkey < 1229
select c_nationkey, o_custkey, n_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000060617' AND o_orderdate < '1995-11-01' AND o_comment = 'ly around the pending theodo' order by c_nationkey ASC, n_regionkey DESC, r_name ASC
select o_shippriority from orders where o_orderpriority > '3-MEDIUM' AND o_orderstatus <= 'O' AND o_orderpriority >= '4-NOT SPECIFIED' AND o_orderkey = 1472992 order by o_shippriority ASC
select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where ps_availqty = 8724 AND p_size > 31 AND p_retailprice >= 1295.27 AND l_orderkey < 2618950 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by ps_partkey DESC, p_name ASC
SELECT l_commitdate, c_comment, o_custkey, n_name, r_comment FROM lineitem JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey WHERE n_comment < 'ously. final, express gifts cajole a' AND c_phone > '22-307-505-3469' ORDER BY n_name DESC, c_comment DESC, l_commitdate DESC
select s_comment, ps_partkey, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000001926' AND l_partkey > 177828 group by s_comment, ps_partkey, l_shipmode having min(s_name) <= 'Supplier#000003848' order by sum(ps_partkey) DESC, min(s_name) ASC
SELECT l_returnflag, o_clerk, c_custkey, MIN(o_totalprice) FROM lineitem JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE l_extendedprice = 72872.0 AND c_custkey > 42930 GROUP BY l_returnflag, o_clerk, c_custkey HAVING MIN(o_totalprice) >= 343885.86 ORDER BY MIN(o_totalprice) DESC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('29', '33', '11', '19', '28', '27', '15')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('29', '33', '11', '19', '28', '27', '15')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'ARGENTINA' and n2.n_name = 'FRANCE')     or (n1.n_name = 'FRANCE' and n2.n_name = 'ARGENTINA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
SELECT ps_supplycost, l_receiptdate, o_totalprice, p_container FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE l_linestatus < 'O' AND o_orderpriority <> '5-LOW' AND l_shipinstruct > 'TAKE BACK RETURN' ORDER BY o_totalprice DESC
select s_nationkey, s_comment from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 9048 AND s_nationkey < 17 AND ps_supplycost <= 718.7 AND s_acctbal < 4975.09 AND ps_supplycost > 422.84 AND ps_partkey <= 56821
SELECT l_discount, ps_supplycost, s_name, o_orderstatus FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE l_returnflag <> 'N' AND l_discount = 0.06 AND l_receiptdate = '1996-07-13' ORDER BY s_name DESC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#41'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 8 and l_quantity <= 8 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#51'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 20 and l_quantity <= 20 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 21 and l_quantity <= 21 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT l_commitdate, ps_supplycost FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_receiptdate >= '1998-09-27' AND ps_supplycost <= 983.45 AND l_linenumber < 7 AND ps_suppkey < 5063 AND l_extendedprice >= 26883.18 AND l_shipmode = 'REG AIR' AND l_returnflag = 'A' ORDER BY l_commitdate ASC, ps_supplycost DESC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#22'  and p_type not like 'ECONOMY BURNISHED%'  and p_size in (21, 35, 11, 3, 23, 20, 44, 27)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select l_orderkey, p_size, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_extendedprice = 35350.56 AND p_type = 'STANDARD BRUSHED STEEL' AND l_commitdate = '1998-10-10' AND l_orderkey < 2618950 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by ps_partkey DESC, p_size ASC
select l_shipdate, ps_availqty from lineitem, partsupp where l_linestatus = 'F' AND l_shipinstruct = 'TAKE BACK RETURN' AND l_tax = 0.07 AND ps_partkey = 99097
SELECT l_linenumber, o_orderkey FROM orders JOIN lineitem ON l_orderkey = o_orderkey WHERE o_orderstatus > 'F' AND l_suppkey = 5491 AND o_custkey <> 140612 AND l_shipinstruct <= 'COLLECT COD'
select p_mfgr, ps_availqty, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 9188 AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 56821 group by p_mfgr, ps_availqty having min(p_container) = 'JUMBO CASE'
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#51'  and p_container = 'LG CASE'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '67' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'DELIVER IN PERSON' AND s_name = 'Supplier#000000986' AND s_suppkey = 9076 order by ps_partkey DESC, s_name ASC
select l_receiptdate, o_totalprice from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 168844.46 AND l_tax > 0.0 AND o_custkey > 136606 order by o_totalprice DESC, l_receiptdate ASC
SELECT l_linenumber, o_custkey, c_acctbal FROM lineitem JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE o_orderkey <> 654052 AND c_comment <= 'final requests. accounts alongside' AND l_orderkey <= 1744545 AND l_discount = 0.04 AND c_custkey >= 46714
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('13', '28', '20', '34', '23', '17', '12')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('13', '28', '20', '34', '23', '17', '12')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT s_phone, r_regionkey, ps_suppkey, n_comment FROM region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey WHERE n_regionkey < 1 AND ps_availqty <= 5354 AND s_nationkey <> 1 ORDER BY s_phone DESC, ps_suppkey DESC, n_comment DESC, r_regionkey ASC
select ps_suppkey, n_comment, s_name, n_regionkey, count(ps_suppkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 8448 group by ps_suppkey, n_regionkey, s_name, n_comment order by ps_suppkey DESC, s_name DESC
select  o_year,  sum(case   when nation = 'RUSSIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM POLISHED TIN'  ) as all_nations group by  o_year order by  o_year ;
select l_partkey, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1995-09-02' AND l_returnflag = 'R' AND ps_availqty >= 9048 AND l_shipinstruct = 'NONE'
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'MAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT l_partkey, ps_supplycost FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_tax = 0.07 AND ps_availqty = 9934 AND ps_suppkey <= 9755 AND l_shipmode <> 'AIR'
SELECT o_comment, c_name FROM customer, orders WHERE o_orderstatus > 'P' AND o_shippriority > 0 AND o_totalprice >= 282330.75 AND c_comment >= 'ly express packages are about the quickly bold foxes. final dependencies after the quickly idle acco' AND c_mktsegment < 'FURNITURE'
select c_nationkey, o_orderstatus, n_comment from orders, customer, nation where o_totalprice < 36447.99 AND c_acctbal = 799.99 AND c_name = 'Customer#000134672' AND c_mktsegment > 'FURNITURE' AND o_shippriority < 0
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#35'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 8 and l_quantity <= 8 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#35'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 19 and l_quantity <= 19 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 25 and l_quantity <= 25 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT o_orderpriority, c_custkey, SUM(c_nationkey) FROM customer, orders WHERE o_comment > 'kages. blithely bold platelets play fluffily pending frets. slyly final ins' AND o_orderstatus > 'P' AND c_name > 'Customer#000070744' AND o_orderpriority < '4-NOT SPECIFIED' AND c_comment < 'furiously regular theodolites will haggle. slyly pending instructions sleep carefully regular accounts.' GROUP BY o_orderpriority, c_custkey HAVING SUM(c_nationkey) = 18 ORDER BY SUM(c_nationkey) DESC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#21'  and p_type not like 'SMALL BURNISHED%'  and p_size in (37, 31, 29, 26, 15, 19, 42, 8)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1994-04-01'  and l_shipdate < date '1994-04-01' + interval '1' month ;
select c_nationkey, o_custkey, r_comment, o_orderpriority from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where r_name >= 'MIDDLE EAST' AND o_orderdate < '1995-01-28' AND o_comment = 'ggle. carefully ironic ideas' order by c_nationkey ASC, o_orderpriority DESC, o_custkey ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('14', '11', '13', '29', '26', '34', '19')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('14', '11', '13', '29', '26', '34', '19')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#44'  and p_type not like 'LARGE PLATED%'  and p_size in (28, 46, 17, 37, 13, 47, 35, 8)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT l_returnflag, ps_partkey, p_brand FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE ps_partkey <= 108173 AND p_retailprice = 1789.88 AND l_shipdate < '1995-06-16' ORDER BY l_returnflag ASC, p_brand ASC, ps_partkey ASC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'KENYA' and n2.n_name = 'PERU')     or (n1.n_name = 'PERU' and n2.n_name = 'KENYA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
SELECT c_custkey, o_clerk FROM customer JOIN orders ON o_custkey = c_custkey WHERE o_clerk = 'Clerk#000000885' AND o_custkey > 99901 AND c_phone >= '33-977-252-8569' AND o_orderpriority < '2-HIGH'
SELECT l_suppkey, ps_suppkey FROM partsupp, lineitem WHERE l_shipinstruct <> 'NONE' AND l_linenumber >= 1 AND l_extendedprice > 93257.76 AND ps_partkey > 5023 AND l_commitdate = '1995-02-08'
select p_mfgr, ps_availqty, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 2301 AND p_mfgr = 'Manufacturer#3' AND ps_partkey <= 180166 group by p_mfgr, ps_availqty having min(p_container) = 'JUMBO CASE'
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('TRUCK', 'FOB')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#31'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 3 and l_quantity <= 3 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#15'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 13 and l_quantity <= 13 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#11'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 20 and l_quantity <= 20 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'BRAZIL' and n2.n_name = 'EGYPT')     or (n1.n_name = 'EGYPT' and n2.n_name = 'BRAZIL')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  o_year,  sum(case   when nation = 'INDIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL BURNISHED TIN'  ) as all_nations group by  o_year order by  o_year ;
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'NONE' AND s_name = 'Supplier#000000551' AND s_suppkey = 2333 order by ps_partkey DESC, s_name DESC
SELECT ps_comment, l_linestatus FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_discount >= 0.01 AND l_shipinstruct >= 'DELIVER IN PERSON' AND l_returnflag > 'R' AND ps_availqty < 6827 AND l_receiptdate >= '1993-01-03' ORDER BY l_linestatus DESC
SELECT ps_suppkey, l_shipmode, o_orderstatus, p_type FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE l_quantity = 42.0 AND l_receiptdate >= '1998-02-12' AND o_comment >= 'oxes are closely fluffily'
SELECT n_comment, o_orderstatus, c_address FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE c_nationkey <= 23 AND c_comment < 'ng, unusual theodolites integrate blithely regular, bold packages. carefully regular packag' AND o_totalprice >= 324917.0 ORDER BY n_comment DESC, c_address DESC, o_orderstatus DESC
SELECT c_custkey, o_custkey FROM orders JOIN customer ON c_custkey = o_custkey WHERE o_orderkey < 3675364 AND c_address = 'Cw1dfnVm7A OPhKlde2NaEdxAu7L5QBYR' AND c_custkey <> 140986 AND o_orderstatus < 'O' ORDER BY c_custkey ASC, o_custkey DESC
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#35'  and p_container = 'WRAP PACK'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 26  and p_type like '%BRASS'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%yellow%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select ps_partkey, ps_availqty, l_orderkey, min(l_suppkey), sum(l_quantity) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone <= '17-292-821-2297' AND s_name < 'Supplier#000001926' AND l_partkey > 167548 group by l_orderkey, ps_partkey, ps_availqty having min(l_suppkey) <= 3346 order by sum(l_quantity) DESC, min(l_suppkey) ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 13  and p_type like '%BRASS'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
