select s_comment, ps_partkey, s_name, min(l_shipmode), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_name = 'Supplier#000006725' AND l_partkey < 96753 AND s_phone > '30-627-214-4834' group by s_comment, ps_partkey, s_name having min(l_shipmode) <= 'TRUCK' order by sum(ps_partkey) DESC, min(l_shipmode) ASC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#45'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 5 and l_quantity <= 5 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 18 and l_quantity <= 18 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#15'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 27 and l_quantity <= 27 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  n_name,  sum(l_extendedprice * (1 - l_discount)) as revenue from  customer,  orders,  lineitem,  supplier,  nation,  region where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and l_suppkey = s_suppkey  and c_nationkey = s_nationkey  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AFRICA'  and o_orderdate >= date '1993-01-01'  and o_orderdate < date '1993-01-01' + interval '1' year group by  n_name order by  revenue desc ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 33  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('TRUCK', 'MAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  o_year,  sum(case   when nation = 'GERMANY' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO BURNISHED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
SELECT l_returnflag, s_comment, ps_availqty FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey WHERE l_linenumber <= 4 AND l_orderkey <> 417382 AND ps_partkey = 74866 AND l_discount < 0.01 ORDER BY s_comment DESC, l_returnflag DESC
SELECT ps_comment FROM partsupp WHERE ps_suppkey >= 9546 AND ps_supplycost <> 558.99 AND ps_availqty <= 3951 AND ps_comment >= 'e the furiously final packages. unusual accounts hinder special accounts. furiously express accounts us' ORDER BY ps_comment DESC
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'brown%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1993-01-01'      and l_shipdate < date '1993-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'CANADA' order by  s_name ;
SELECT ps_availqty FROM partsupp WHERE ps_suppkey <= 3039 AND ps_availqty >= 9934 AND ps_comment < 'ular requests boost pinto beans. even, regular deposits cajole according to the regular foxes. even deposits according to the bravely daring requests print caref' AND ps_partkey < 55775 ORDER BY ps_availqty DESC
SELECT o_orderpriority, MAX(o_orderkey) FROM orders WHERE o_clerk = 'Clerk#000000556' AND o_custkey >= 133936 AND o_comment <= 'sits unwind furiously. blithel' GROUP BY o_orderpriority HAVING MAX(o_orderkey) <> 5400517 ORDER BY o_orderpriority DESC
SELECT ps_suppkey, p_size FROM part, partsupp WHERE ps_partkey < 92663 AND ps_comment <= 'ake furiously blithe requests. permanently ruthless accounts cajole along the boldly regular attainments. quickly regular' AND ps_supplycost > 504.43 AND p_comment = 'und the quickl' AND p_mfgr <> 'Manufacturer#3' AND p_retailprice = 1231.3 ORDER BY ps_suppkey ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('11', '15', '19', '12', '34', '13', '28')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('11', '15', '19', '12', '34', '13', '28')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('TRUCK', 'FOB')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1994-01-01'  and l_receiptdate < date '1994-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  o_year,  sum(case   when nation = 'PERU' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'STANDARD ANODIZED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
SELECT l_commitdate, ps_availqty FROM lineitem, partsupp WHERE l_linestatus <> 'F' AND l_orderkey < 56675 AND l_tax < 0.07 AND l_extendedprice = 41364.0
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 24  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select l_orderkey, p_name, l_commitdate from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_orderkey = 1446724 AND p_type = 'STANDARD BRUSHED STEEL' AND ps_partkey = 5023 AND l_linestatus < 'O' AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by p_name DESC, l_commitdate ASC
select s_comment, ps_partkey, l_shipdate, min(l_orderkey), sum(s_acctbal) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000001926' AND l_partkey > 167548 group by s_comment, ps_partkey, l_shipdate having min(l_orderkey) <= 4693120 order by sum(s_acctbal) DESC, min(l_orderkey) ASC
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1993-01-01'  and l_shipdate < date '1993-01-01' + interval '1' year  and l_discount between 0.07 - 0.01 and 0.07 + 0.01  and l_quantity < 25 ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 14  and p_type like '%BRASS'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  n_name,  sum(l_extendedprice * (1 - l_discount)) as revenue from  customer,  orders,  lineitem,  supplier,  nation,  region where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and l_suppkey = s_suppkey  and c_nationkey = s_nationkey  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and o_orderdate >= date '1997-01-01'  and o_orderdate < date '1997-01-01' + interval '1' year group by  n_name order by  revenue desc ;
SELECT o_orderkey, c_comment, r_regionkey, n_regionkey FROM orders, customer, nation, region WHERE o_comment = 'iously final requests; final deposits are express, express pint' AND c_address = 'W1JsrGuSWitekBCkHs9,9ORda9iJMXTNtMAlq' AND n_nationkey > 6 ORDER BY n_regionkey ASC, r_regionkey DESC, c_comment ASC
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1995-01-01'  and l_shipdate < date '1995-01-01' + interval '1' year  and l_discount between 0.05 - 0.01 and 0.05 + 0.01  and l_quantity < 24 ;
select ps_suppkey, r_regionkey, s_nationkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_comment > 's across the careful pinto beans are boldly across the regular' AND ps_suppkey >= 7114 group by n_regionkey, r_regionkey, s_nationkey, ps_suppkey order by ps_suppkey DESC, r_regionkey DESC
select l_shipinstruct, o_totalprice from lineitem, orders where o_shippriority >= 0 AND o_orderstatus = 'F' AND l_suppkey = 8624 AND l_extendedprice = 28681.83
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '78' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select c_nationkey, c_acctbal, o_custkey, o_comment from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000146510' AND o_orderdate < '1997-12-20' AND o_comment = 'ggle. carefully ironic ideas' order by c_nationkey ASC, o_custkey DESC, o_comment ASC
SELECT n_name, s_comment, ps_comment, r_comment, MAX(ps_supplycost), COUNT(s_nationkey) FROM partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey WHERE n_regionkey < 0 AND s_acctbal <= 9376.37 GROUP BY n_name, s_comment, ps_comment, r_comment ORDER BY ps_comment DESC, r_comment DESC
select l_suppkey, o_totalprice from lineitem, orders where o_totalprice >= 179706.88 AND o_orderstatus = 'P' AND l_linestatus = 'O' AND l_extendedprice = 28681.83
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'MACHINERY' AND o_orderdate = '1993-03-26' AND o_custkey < 9136 AND o_orderkey < 2232065
SELECT c_address, o_orderpriority FROM customer JOIN orders ON o_custkey = c_custkey WHERE o_orderdate = '1992-11-21' AND o_totalprice > 63471.44 AND c_address <= 'gzNtUmM66Zw' AND o_orderpriority >= '3-MEDIUM' ORDER BY c_address ASC, o_orderpriority ASC
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'FURNITURE'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-28'  and l_shipdate > date '1995-03-28' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
SELECT o_orderkey, l_partkey, ps_partkey FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_linenumber <= 1 AND ps_suppkey > 9208 AND o_orderdate <= '1995-08-03' AND l_extendedprice = 74957.22
select l_commitdate, l_shipdate from lineitem, partsupp where ps_comment > 'e the furiously final packages. unusual accounts hinder special accounts. furiously express accounts us' AND ps_suppkey < 2099 AND l_tax < 0.07 AND l_extendedprice = 41364.0
SELECT p_name, n_regionkey, ps_comment, s_phone FROM nation JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey WHERE p_brand > 'Brand#25' AND s_nationkey <= 10 AND ps_partkey <= 27306 AND p_retailprice < 1321.33 ORDER BY p_name DESC, ps_comment DESC
select ps_partkey, s_suppkey, s_name from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'NONE' AND s_name = 'Supplier#000000551' AND l_comment = 'regular sauternes. excuses haggle a' order by ps_partkey DESC, s_name ASC
select s_comment, ps_partkey, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000001926' AND l_partkey > 77293 group by s_comment, ps_partkey, l_shipmode having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#24'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 6 and l_quantity <= 6 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#22'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 12 and l_quantity <= 12 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#51'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 30 and l_quantity <= 30 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT l_receiptdate, o_comment, ps_suppkey, c_name, s_phone FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE c_custkey > 150000 AND ps_comment = 'e the furiously final packages. unusual accounts hinder special accounts. furiously express accounts us' AND l_tax <= 0.05 ORDER BY s_phone ASC
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'midnight%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1995-01-01'      and l_shipdate < date '1995-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'UNITED KINGDOM' order by  s_name ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#33'  and p_container = 'JUMBO CASE'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT s_phone, ps_supplycost, n_nationkey, p_container FROM nation, supplier, partsupp, part WHERE n_name > 'BRAZIL' AND p_retailprice = 1236.16 AND n_nationkey = 13 AND p_name > 'snow bisque rosy pink pale' AND s_suppkey = 3861 AND s_nationkey > 14 AND ps_supplycost < 718.28 ORDER BY ps_supplycost DESC, s_phone DESC
SELECT l_receiptdate FROM lineitem WHERE l_receiptdate < '1998-01-15' AND l_extendedprice = 12972.48 AND l_shipinstruct <> 'NONE' AND l_returnflag >= 'A' AND l_tax < 0.06
