select ps_availqty, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate < '1995-09-02' AND l_partkey > 69559 AND l_returnflag >= 'N' AND l_shipinstruct = 'NONE'
SELECT ps_suppkey, l_shipmode FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_suppkey < 3436 AND l_discount > 0.1 AND l_quantity <= 35.0 AND ps_supplycost < 114.96
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#22'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 8 and l_quantity <= 8 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#22'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 19 and l_quantity <= 19 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#44'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 29 and l_quantity <= 29 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  o_year,  sum(case   when nation = 'RUSSIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL ANODIZED STEEL'  ) as all_nations group by  o_year order by  o_year ;
SELECT p_name, ps_supplycost FROM partsupp, part WHERE ps_comment <> 'ar packages wake thinly bold pinto beans. silent foxes print carefully-- pinto bean' AND p_size > 25 AND ps_suppkey >= 6273 AND p_comment = 'eodol'
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#35'  and p_type not like 'MEDIUM PLATED%'  and p_size in (2, 13, 15, 48, 34, 6, 20, 26)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'CANADA' and n2.n_name = 'EGYPT')     or (n1.n_name = 'EGYPT' and n2.n_name = 'CANADA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  o_year,  sum(case   when nation = 'EGYPT' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM POLISHED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select l_shipinstruct, l_partkey, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where p_retailprice = 1248.17 AND ps_comment = 'lent accounts detect quickly accounts. regularly regular foxes haggle furiously. foxes use alongside of the special, pending pinto beans. deposits sleep. furiously unu' AND l_shipmode = 'SHIP' AND ps_comment <= 'ions. express, even requests cajole carefully. silent foxes wake. blithely ironic pinto beans boost quickly regular instructions. fluffily pending dependencies are alongside of the pinto beans.'
select ps_availqty, p_name, p_container from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 120307 AND ps_comment > 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND l_shipmode = 'SHIP' AND p_retailprice <= 1831.73
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#22'  and p_container = 'MED BAG'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'RUSSIA' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'RUSSIA'   ) order by  value desc ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'purple%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1995-01-01'      and l_shipdate < date '1995-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'KENYA' order by  s_name ;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '100' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  o_year,  sum(case   when nation = 'MOZAMBIQUE' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AFRICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL BRUSHED TIN'  ) as all_nations group by  o_year order by  o_year ;
SELECT n_name, c_nationkey, s_address FROM supplier, nation, customer WHERE c_address >= 'IY2d0fJl5yMCvbD043ty5scfVfpxbHc6CJ' AND c_mktsegment >= 'MACHINERY' AND s_address = 'HdteuyoPpBVg' ORDER BY n_name ASC
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 9048 AND s_comment < 'ic requests nag. blithely regular ideas try to wake quickly eve' AND ps_partkey <= 91752 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 892.42
SELECT l_returnflag, s_comment, ps_partkey FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey WHERE l_returnflag < 'R' AND l_receiptdate <= '1993-08-24' AND ps_suppkey > 8879 AND s_nationkey = 24 AND l_extendedprice < 6394.08
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1997-09-01'  and l_shipdate < date '1997-09-01' + interval '1' month ;
select l_commitdate, ps_availqty from lineitem, partsupp where l_extendedprice = 38634.96 AND l_orderkey < 56675 AND l_tax < 0.02 AND l_linestatus = 'F'
SELECT p_retailprice, ps_availqty FROM partsupp JOIN part ON p_partkey = ps_partkey WHERE ps_comment <> 'foxes. bold, special deposits doze carefully alongside of the requests. boldly regular accounts haggle. special the' AND ps_partkey > 89084 AND ps_suppkey >= 5599 AND p_comment <> 'ironic dependenc'
SELECT s_acctbal, l_suppkey, ps_partkey, n_comment, MAX(s_suppkey) FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey WHERE l_discount <= 0.09 AND l_extendedprice = 57611.07 GROUP BY s_acctbal, l_suppkey, ps_partkey, n_comment HAVING MAX(s_suppkey) = 9870
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#43'  and p_container = 'WRAP JAR'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#44'  and p_container = 'WRAP DRUM'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%lawn%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select l_commitdate, ps_availqty from lineitem, partsupp where l_linestatus = 'O' AND l_orderkey < 56675 AND l_tax < 0.07 AND l_extendedprice = 41364.0
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#44'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 6 and l_quantity <= 6 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#13'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 16 and l_quantity <= 16 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#23'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 25 and l_quantity <= 25 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT l_shipmode, o_orderstatus, r_regionkey, c_nationkey, n_comment FROM region JOIN nation ON n_regionkey = r_regionkey JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE c_phone > '24-209-167-5711' AND l_shipdate < '1997-06-10' ORDER BY r_regionkey ASC
select l_orderkey, ps_supplycost, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where l_extendedprice = 54745.6 AND s_name < 'Supplier#000001926' AND l_partkey > 167548 group by ps_supplycost, l_orderkey, l_shipmode having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'HOUSEHOLD'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-06'  and l_shipdate > date '1995-03-06' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select p_mfgr, ps_availqty, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 9188 AND ps_partkey = 143679 AND p_mfgr <= 'Manufacturer#5' group by ps_availqty, p_mfgr having min(p_container) = 'JUMBO CASE'
select c_nationkey, o_orderstatus, o_orderpriority from orders, customer, nation where o_totalprice < 242911.86 AND c_acctbal = 1481.44 AND o_orderdate = '1998-05-30' AND n_nationkey >= 11 AND o_shippriority < 0
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#35'  and p_type not like 'MEDIUM BURNISHED%'  and p_size in (49, 4, 24, 32, 20, 47, 43, 23)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select c_nationkey, o_custkey, n_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000069739' AND o_orderdate < '1995-01-28' AND o_comment = 'ions haggle carefully above the ironic realms. regula' order by c_nationkey ASC, n_regionkey DESC, r_name ASC
SELECT r_regionkey, ps_suppkey, s_nationkey, n_regionkey FROM partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey WHERE r_name = 'MIDDLE EAST' AND s_name >= 'Supplier#000007968' AND s_suppkey <> 9341 AND s_nationkey > 8
select ps_suppkey, r_regionkey, s_nationkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_comment > 'ts are carefully blithely' AND ps_suppkey >= 8448 group by ps_suppkey, n_regionkey, r_regionkey, s_nationkey order by ps_suppkey DESC, r_regionkey DESC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 47  and p_type like '%COPPER'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AFRICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AFRICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT o_orderpriority, l_extendedprice, c_mktsegment, MIN(o_orderpriority) FROM lineitem JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE l_partkey <> 134622 AND c_name <> 'Customer#000134672' AND c_phone >= '31-508-135-3622' GROUP BY o_orderpriority, l_extendedprice, c_mktsegment ORDER BY l_extendedprice ASC, o_orderpriority ASC, c_mktsegment ASC
select  o_year,  sum(case   when nation = 'SAUDI ARABIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'ECONOMY ANODIZED STEEL'  ) as all_nations group by  o_year order by  o_year ;
SELECT o_orderkey, n_name, c_custkey, r_comment, MIN(n_comment) FROM region JOIN nation ON n_regionkey = r_regionkey JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE c_address = 'W1JsrGuSWitekBCkHs9,9ORda9iJMXTNtMAlq' AND o_comment <> 'posits use carefully daringly final foxes. blithe' AND c_comment > 'ously final deposits breach fluffily silent, silent' GROUP BY o_orderkey, n_name, c_custkey, r_comment ORDER BY MIN(n_comment) DESC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('24', '25', '33', '21', '12', '26', '32')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('24', '25', '33', '21', '12', '26', '32')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1994-03-01'  and o_orderdate < date '1994-03-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select l_shipinstruct, ps_availqty from lineitem, partsupp where ps_supplycost = 943.73 AND l_orderkey < 56675 AND l_linestatus >= 'O' AND l_extendedprice = 41364.0
select c_nationkey, o_custkey, n_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000060617' AND o_orderdate = '1993-02-17' AND o_comment = 'ggle. carefully ironic ideas' order by o_custkey DESC, n_regionkey DESC, r_name ASC
select  n_name,  sum(l_extendedprice * (1 - l_discount)) as revenue from  customer,  orders,  lineitem,  supplier,  nation,  region where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and l_suppkey = s_suppkey  and c_nationkey = s_nationkey  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and o_orderdate >= date '1994-01-01'  and o_orderdate < date '1994-01-01' + interval '1' year group by  n_name order by  revenue desc ;
