select  n_name,  sum(l_extendedprice * (1 - l_discount)) as revenue from  customer,  orders,  lineitem,  supplier,  nation,  region where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and l_suppkey = s_suppkey  and c_nationkey = s_nationkey  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and o_orderdate >= date '1995-01-01'  and o_orderdate < date '1995-01-01' + interval '1' year group by  n_name order by  revenue desc ;
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where o_orderkey < 4400768 AND o_orderdate = '1993-09-18' AND o_custkey < 9136 AND c_mktsegment < 'BUILDING'
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1997-05-01'  and l_shipdate < date '1997-05-01' + interval '1' month ;
select c_nationkey, o_orderstatus, n_comment from orders, customer, nation where o_totalprice < 65599.68 AND c_acctbal = 7232.97 AND c_name = 'Customer#000060617' AND c_mktsegment > 'HOUSEHOLD' AND o_shippriority < 0
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'white%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1994-01-01'      and l_shipdate < date '1994-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'JORDAN' order by  s_name ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('MAIL', 'AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select c_nationkey, o_orderstatus, n_comment from orders, customer, nation where o_shippriority < 0 AND c_acctbal = 4998.04 AND c_name = 'Customer#000143733' AND o_totalprice > 112609.58 AND c_mktsegment < 'HOUSEHOLD'
select s_comment, l_shipmode, l_partkey, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where ps_partkey = 198332 AND s_phone < '11-716-502-9928' AND s_name > 'Supplier#000005222' group by s_comment, l_shipmode, l_partkey having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'FURNITURE'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-11'  and l_shipdate > date '1995-03-11' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'DELIVER IN PERSON' AND s_name = 'Supplier#000000551' AND s_suppkey = 1933 order by ps_partkey DESC, s_name ASC
SELECT l_receiptdate, ps_partkey, s_name, MAX(s_comment), AVG(l_suppkey) FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE ps_suppkey = 6387 AND l_quantity < 10.0 AND s_name = 'Supplier#000007385' GROUP BY l_receiptdate, ps_partkey, s_name ORDER BY s_name ASC, l_receiptdate ASC
SELECT o_orderkey, l_linestatus, n_regionkey, c_comment, ps_partkey FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE o_orderpriority = '3-MEDIUM' AND n_regionkey < 3 AND c_address = 'p4U,vB,Jz3SkV9tKHTOlNgDJ'
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1996-09-01'  and o_orderdate < date '1996-09-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
SELECT r_regionkey, s_acctbal, n_name FROM region, nation, supplier WHERE s_suppkey <= 9076 AND r_regionkey = 0 AND s_address >= '2Nf6B5RqqNb,J,Sjhfc2ui3Z' ORDER BY n_name ASC
select  o_year,  sum(case   when nation = 'ETHIOPIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AFRICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO PLATED TIN'  ) as all_nations group by  o_year order by  o_year ;
select l_partkey, ps_partkey, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_comment = 'uriously regular deposits cajole. blithely ironic requests sleep blithely regular foxes. regular' AND s_name < 'Supplier#000004985' AND s_phone > '12-108-684-2764' group by l_shipmode, ps_partkey, l_partkey having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select l_extendedprice, ps_comment, l_linestatus from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_suppkey = 1961 AND l_linenumber = 3 AND l_shipmode = 'SHIP' AND p_retailprice <= 1831.73
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#34'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 8 and l_quantity <= 8 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#15'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 16 and l_quantity <= 16 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#22'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 23 and l_quantity <= 23 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select l_receiptdate, o_totalprice from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 93025.24 AND o_custkey > 71746 AND l_tax > 0.04 order by o_totalprice DESC, l_receiptdate ASC
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%blush%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select l_commitdate, l_tax from lineitem, partsupp where l_linestatus = 'F' AND l_orderkey < 3096769 AND ps_availqty < 3886 AND l_extendedprice = 4460.36
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'HOUSEHOLD' AND o_orderkey = 2668161 AND o_custkey < 55810 AND o_orderkey < 4064390
select  o_year,  sum(case   when nation = 'CANADA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'ECONOMY BRUSHED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select p_mfgr, ps_availqty, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 9188 AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 180166 group by p_mfgr, ps_availqty having min(p_container) = 'JUMBO PKG'
select  o_year,  sum(case   when nation = 'EGYPT' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO PLATED STEEL'  ) as all_nations group by  o_year order by  o_year ;
SELECT c_nationkey, o_orderstatus, l_shipinstruct, COUNT(o_totalprice), MAX(c_nationkey) FROM customer JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE c_mktsegment >= 'HOUSEHOLD' AND c_address < 'KKBwEdJZuMRRkEZ' AND c_name = 'Customer#000134672' AND l_partkey <> 177828 GROUP BY c_nationkey, o_orderstatus, l_shipinstruct
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#11'  and p_container = 'WRAP BOX'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'hot%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1997-01-01'      and l_shipdate < date '1997-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'ARGENTINA' order by  s_name ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'turquoise%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1995-01-01'      and l_shipdate < date '1995-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'INDIA' order by  s_name ;
select  c_count,  count(*) as custdist from  (   select    c_custkey,    count(o_orderkey)   from    customer left outer join orders on     c_custkey = o_custkey     and o_comment not like '%pending%accounts%'   group by    c_custkey  ) as c_orders (c_custkey, c_count) group by  c_count order by  custdist desc,  c_count desc ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#53'  and p_type not like 'SMALL BRUSHED%'  and p_size in (22, 33, 38, 29, 7, 23, 5, 12)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('29', '27', '33', '10', '16', '17', '23')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('29', '27', '33', '10', '16', '17', '23')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select s_comment, ps_partkey, l_shipmode, max(l_receiptdate), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_nationkey < 13 AND l_partkey > 167548 group by s_comment, ps_partkey, l_shipmode having sum(ps_partkey) <= 587 order by sum(ps_partkey) DESC, max(l_receiptdate) ASC
select ps_suppkey, s_comment, s_nationkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where ps_suppkey > 6478 AND r_regionkey >= 1 group by ps_suppkey, s_comment, n_regionkey, s_nationkey order by ps_suppkey DESC, s_comment DESC
select  c_count,  count(*) as custdist from  (   select    c_custkey,    count(o_orderkey)   from    customer left outer join orders on     c_custkey = o_custkey     and o_comment not like '%special%deposits%'   group by    c_custkey  ) as c_orders (c_custkey, c_count) group by  c_count order by  custdist desc,  c_count desc ;
SELECT l_tax, p_brand, ps_availqty FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE l_returnflag < 'N' AND ps_comment <> 'uses print after the even packages. furiously regular instructions above the deposits sleep after the blithely ruthless deposits. ca' AND p_name <= 'azure sienna cornflower cyan white' AND p_retailprice > 1583.62 ORDER BY p_brand ASC, l_tax DESC, ps_availqty DESC
SELECT l_shipinstruct FROM lineitem WHERE l_returnflag = 'N' AND l_orderkey < 1218119 AND l_shipinstruct = 'TAKE BACK RETURN' AND l_discount > 0.01 ORDER BY l_shipinstruct DESC
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'JAPAN' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'JAPAN'   ) order by  value desc ;
SELECT p_comment, l_linenumber, ps_comment FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE p_retailprice = 1613.6 AND ps_supplycost >= 362.95 AND ps_availqty = 3938 AND ps_suppkey <> 8274
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#11'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 5 and l_quantity <= 5 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 14 and l_quantity <= 14 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#51'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 24 and l_quantity <= 24 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'IRAN' and n2.n_name = 'IRAQ')     or (n1.n_name = 'IRAQ' and n2.n_name = 'IRAN')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select s_phone, s_name from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 7758 AND ps_partkey < 89084 AND ps_partkey <= 173618 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 8  and p_type like '%STEEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT o_orderstatus, c_nationkey FROM orders, customer WHERE c_nationkey >= 7 AND o_orderstatus <= 'F' AND o_orderdate <= '1992-10-02' AND o_comment <= 'regular dolphins. regular, regular foxes are a' AND c_mktsegment = 'MACHINERY' AND o_shippriority < 0
SELECT l_shipinstruct, c_acctbal, ps_supplycost, o_orderstatus, n_nationkey FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE ps_partkey > 188984 AND l_commitdate = '1998-10-10' ORDER BY l_shipinstruct DESC, n_nationkey ASC
SELECT o_totalprice, l_tax, s_suppkey, ps_partkey FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE ps_partkey <= 188984 AND l_discount = 0.06 AND s_address = 'DeCSqduLu2JE9brcwCj'
SELECT p_mfgr, s_comment, ps_supplycost FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN supplier ON s_suppkey = ps_suppkey WHERE p_type <> 'LARGE ANODIZED BRASS' AND ps_availqty <= 1268 AND s_comment > 'ular deposits should are express foxes. furiously express excuses haggle busily. furiously' ORDER BY p_mfgr ASC
SELECT s_phone, l_returnflag, ps_availqty FROM supplier, partsupp, lineitem WHERE l_comment = 'lar foxes according to the' AND ps_partkey = 188984 AND l_returnflag = 'N' AND l_shipmode <= 'TRUCK'
select l_receiptdate, o_totalprice from orders, lineitem where o_custkey <= 46336 AND o_totalprice = 168844.46 AND o_orderpriority > '2-HIGH' AND l_tax > 0.02 order by o_totalprice DESC, l_receiptdate ASC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#54'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 3 and l_quantity <= 3 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#24'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 16 and l_quantity <= 16 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#11'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 30 and l_quantity <= 30 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT ps_supplycost FROM partsupp WHERE ps_supplycost = 319.5 AND ps_availqty < 3398 AND ps_comment <> 'ake furiously blithe requests. permanently ruthless accounts cajole along the boldly regular attainments. quickly regular' AND ps_partkey >= 142881 ORDER BY ps_supplycost ASC
select l_commitdate, l_linestatus from lineitem, partsupp where ps_availqty = 775 AND l_orderkey < 292129 AND l_tax < 0.07 AND l_extendedprice = 41364.0
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'puff%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1996-01-01'      and l_shipdate < date '1996-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'BRAZIL' order by  s_name ;
select l_shipinstruct, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey > 120307 AND l_commitdate = '1997-11-16' AND p_partkey = 167206 AND p_retailprice <= 1831.73
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#12'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 4 and l_quantity <= 4 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 14 and l_quantity <= 14 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#41'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 20 and l_quantity <= 20 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  o_year,  sum(case   when nation = 'ALGERIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AFRICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO ANODIZED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select  c_custkey,  c_name,  sum(l_extendedprice * (1 - l_discount)) as revenue,  c_acctbal,  n_name,  c_address,  c_phone,  c_comment from  customer,  orders,  lineitem,  nation where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate >= date '1994-12-01'  and o_orderdate < date '1994-12-01' + interval '3' month  and l_returnflag = 'R'  and c_nationkey = n_nationkey group by  c_custkey,  c_name,  c_acctbal,  c_phone,  n_name,  c_address,  c_comment order by  revenue desc limit 20;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#22'  and p_type not like 'MEDIUM BRUSHED%'  and p_size in (33, 2, 13, 50, 28, 26, 43, 25)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select p_partkey, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'N' AND p_brand >= 'Brand#35' AND ps_supplycost = 334.23 AND l_linenumber >= 7 order by l_linenumber DESC, p_partkey ASC
SELECT o_custkey, ps_suppkey, p_comment, l_comment FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE l_commitdate <= '1995-02-08' AND ps_availqty = 8103 AND p_partkey <= 91942 ORDER BY p_comment DESC, l_comment DESC
SELECT l_linestatus, o_custkey FROM orders, lineitem WHERE o_shippriority < 0 AND o_custkey < 49381 AND l_quantity > 5.0 AND o_orderpriority = '5-LOW' AND l_shipmode > 'REG AIR'
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#53'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#43'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 14 and l_quantity <= 14 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#51'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 25 and l_quantity <= 25 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#45'  and p_container = 'JUMBO CAN'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT c_address, o_totalprice FROM orders, customer WHERE c_address <= 'F, Z aS7AIkY OKGFuJhZvk' AND c_name <= 'Customer#000033008' AND o_comment = 'ironic, bold requests wake slyly' AND o_totalprice > 209389.13 ORDER BY o_totalprice ASC
select l_shipinstruct, l_returnflag, p_mfgr from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 120307 AND l_suppkey = 8758 AND l_shipmode = 'SHIP' AND p_retailprice <= 1831.73
SELECT n_name, l_returnflag, o_shippriority, ps_availqty, c_address, r_regionkey FROM region JOIN nation ON n_regionkey = r_regionkey JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE ps_comment = 'ockey players. pinto beans toward the fluffily daring deposits boost bravely packages. blithely ironic pinto beans among the carefully i' AND o_orderkey <= 435462
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#51'  and p_type not like 'SMALL BURNISHED%'  and p_size in (38, 35, 49, 11, 45, 44, 8, 10)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'smoke%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1993-01-01'      and l_shipdate < date '1993-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'BRAZIL' order by  s_name ;
select l_commitdate, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_clerk >= 'Clerk#000000879' AND l_partkey = 141608 AND l_returnflag >= 'N' AND l_shipinstruct = 'NONE'
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1997-01-01'  and o_orderdate < date '1997-01-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select l_shipinstruct, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 49449 AND ps_comment = 'e the furiously final packages. unusual accounts hinder special accounts. furiously express accounts us' AND l_shipmode = 'RAIL' AND p_retailprice <= 1192.23
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#32'  and p_type not like 'MEDIUM PLATED%'  and p_size in (17, 31, 4, 32, 2, 33, 26, 1)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT l_partkey, o_orderdate, ps_comment, MIN(ps_availqty) FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_extendedprice > 1004.0 AND o_shippriority > 0 GROUP BY l_partkey, o_orderdate, ps_comment HAVING MIN(ps_availqty) <> 1601 ORDER BY ps_comment DESC, l_partkey ASC, o_orderdate DESC
select c_nationkey, o_custkey, o_comment, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_address = '5wxvINnHmM8FmuZtkeglGLpwn8pWcZc031QNTAW' AND o_orderdate < '1995-01-28' AND o_comment = 'ggle. carefully ironic ideas' order by c_nationkey ASC, r_name DESC, o_comment ASC
SELECT l_extendedprice, ps_partkey FROM partsupp, lineitem WHERE l_returnflag > 'N' AND l_tax >= 0.02 AND l_extendedprice = 49926.12 AND l_orderkey <> 4099425 ORDER BY l_extendedprice ASC, ps_partkey ASC
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'N' AND p_brand > 'Brand#42' AND ps_supplycost = 334.23 AND l_linenumber = 7 order by p_mfgr DESC, l_linenumber ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#53'  and p_type not like 'LARGE BURNISHED%'  and p_size in (14, 37, 48, 36, 30, 12, 38, 46)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT s_nationkey, o_shippriority, c_phone, ps_partkey, l_extendedprice, n_nationkey FROM supplier JOIN nation ON n_nationkey = s_nationkey JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_orderkey <> 3179841 AND o_shippriority > 0
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('13', '26', '15', '22', '17', '32', '27')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('13', '26', '15', '22', '17', '32', '27')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT l_suppkey, s_address, ps_partkey FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE s_acctbal <= 3019.76 AND l_extendedprice = 55105.5 AND s_comment >= 'quickly regular pinto beans. fluffily' AND l_orderkey <> 2387522 AND l_linenumber >= 2 ORDER BY s_address ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('23', '30', '24', '22', '13', '12', '31')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('23', '30', '24', '22', '13', '12', '31')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty = 9048 AND s_suppkey = 151 AND ps_partkey <= 173618 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'FRANCE' and n2.n_name = 'GERMANY')     or (n1.n_name = 'GERMANY' and n2.n_name = 'FRANCE')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1994-01-01'  and l_shipdate < date '1994-01-01' + interval '1' year  and l_discount between 0.03 - 0.01 and 0.03 + 0.01  and l_quantity < 24 ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 49  and p_type like '%BRASS'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT l_shipmode, s_suppkey, ps_partkey FROM supplier, partsupp, lineitem WHERE ps_partkey = 32494 AND l_shipdate > '1998-05-28' AND s_comment <> 'fluffily. bold instructions thrash' AND l_linenumber >= 6 AND ps_supplycost > 691.98 AND s_suppkey > 9076 AND s_name = 'Supplier#000006725'
SELECT s_address, ps_suppkey FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey WHERE s_nationkey <= 11 AND ps_partkey <= 75427 AND ps_supplycost > 996.79 AND ps_comment >= 'gainst the slyly regular requests x-ray dependencies. even, regular requests wake carefully special asymptotes. requests run according to the slyly final requests. c' ORDER BY s_address ASC, ps_suppkey DESC
select s_comment, l_comment, l_shipmode, min(ps_partkey), sum(l_discount) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where ps_comment = 'boost slyly regular sentiments. fluffily bold dependencies are special requests. sp' AND s_name = 'Supplier#000001926' AND l_partkey > 167548 group by s_comment, l_comment, l_shipmode having min(ps_partkey) <= 4732 order by sum(l_discount) DESC, min(ps_partkey) ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('10', '26', '33', '32', '34', '11', '31')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('10', '26', '33', '32', '34', '11', '31')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT o_clerk, l_tax, c_name FROM customer JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE l_extendedprice > 1587.61 AND l_shipdate > '1993-08-01' AND l_quantity > 48.0 AND l_returnflag >= 'R' ORDER BY o_clerk ASC, c_name ASC, l_tax DESC
SELECT l_comment, ps_comment FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_linenumber = 4 AND ps_partkey < 71581 AND l_quantity < 2.0 AND l_tax = 0.04 AND l_linestatus > 'F'
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'IRAQ' and n2.n_name = 'SAUDI ARABIA')     or (n1.n_name = 'SAUDI ARABIA' and n2.n_name = 'IRAQ')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
SELECT l_shipdate, ps_suppkey, MAX(l_commitdate), SUM(ps_availqty) FROM partsupp, lineitem WHERE l_linenumber < 1 AND l_linestatus <= 'F' GROUP BY l_shipdate, ps_suppkey HAVING SUM(ps_availqty) <> 4976 AND MAX(l_commitdate) = '1994-04-29' ORDER BY SUM(ps_availqty) DESC
SELECT c_nationkey, o_custkey, n_comment, r_name FROM orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey WHERE o_orderdate > '1998-04-15' AND o_orderkey > 2668161 AND r_name <> 'AMERICA' ORDER BY c_nationkey ASC
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1997-08-01'  and o_orderdate < date '1997-08-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
SELECT l_commitdate, ps_suppkey FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_suppkey = 7722 AND l_returnflag < 'R' AND ps_availqty = 3676 AND l_shipinstruct > 'DELIVER IN PERSON' AND l_discount = 0.01 ORDER BY l_commitdate ASC
SELECT ps_comment, l_discount FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_tax <= 0.08 AND l_receiptdate <> '1994-12-01' AND ps_supplycost = 835.16 AND l_suppkey < 5399
select  s_name,  count(*) as numwait from  supplier,  lineitem l1,  orders,  nation where  s_suppkey = l1.l_suppkey  and o_orderkey = l1.l_orderkey  and o_orderstatus = 'F'  and l1.l_receiptdate > l1.l_commitdate  and exists (   select    *   from    lineitem l2   where    l2.l_orderkey = l1.l_orderkey    and l2.l_suppkey <> l1.l_suppkey  )  and not exists (   select    *   from    lineitem l3   where    l3.l_orderkey = l1.l_orderkey    and l3.l_suppkey <> l1.l_suppkey    and l3.l_receiptdate > l3.l_commitdate  )  and s_nationkey = n_nationkey  and n_name = 'UNITED KINGDOM' group by  s_name order by  numwait desc,  s_name limit 100;
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'NONE' AND s_name = 'Supplier#000000551' AND s_suppkey = 9223 order by ps_partkey DESC, s_name ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#23'  and p_type not like 'ECONOMY BURNISHED%'  and p_size in (31, 28, 7, 41, 16, 37, 26, 49)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select o_orderpriority, c_custkey, n_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000060165' AND o_orderdate < '1995-01-28' AND o_comment = 'inally pending packages sleep along the furiously special' order by r_name ASC, n_regionkey ASC, o_orderpriority ASC
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1996-06-01'  and o_orderdate < date '1996-06-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('22', '10', '33', '13', '28', '17', '26')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('22', '10', '33', '13', '28', '17', '26')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select o_custkey, o_totalprice from orders, lineitem where l_receiptdate <= '1993-08-28' AND l_tax = 0.07 AND o_totalprice > 190711.54 AND o_orderpriority > '3-MEDIUM' order by o_totalprice DESC, o_custkey ASC
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'N' AND p_brand > 'Brand#23' AND ps_supplycost = 334.23 AND l_linenumber = 5 order by p_mfgr DESC, l_linenumber ASC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 7 and l_quantity <= 7 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#23'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 12 and l_quantity <= 12 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#35'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 27 and l_quantity <= 27 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  o_year,  sum(case   when nation = 'ETHIOPIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AFRICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL ANODIZED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'BUILDING'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-23'  and l_shipdate > date '1995-03-23' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select l_comment, s_suppkey, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'TAKE BACK RETURN' AND s_name = 'Supplier#000000551' AND s_name = 'Supplier#000000986' order by ps_partkey DESC, s_suppkey ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#23'  and p_type not like 'LARGE POLISHED%'  and p_size in (31, 12, 29, 39, 11, 30, 21, 13)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'BUILDING'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-08'  and l_shipdate > date '1995-03-08' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select l_receiptdate, o_custkey from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 211151.4 AND l_tax > 0.06 AND o_totalprice > 166162.65 order by l_receiptdate DESC, o_custkey ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#45'  and p_type not like 'LARGE BURNISHED%'  and p_size in (16, 44, 30, 37, 6, 26, 32, 5)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 2  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select c_nationkey, c_custkey, n_comment from orders, customer, nation where o_custkey > 88406 AND c_comment = 'refully final requests? even deposits are according to the blithely unusual packages. slyly express deposits' AND c_name = 'Customer#000143733' AND c_mktsegment > 'BUILDING' AND o_shippriority < 0
select  c_custkey,  c_name,  sum(l_extendedprice * (1 - l_discount)) as revenue,  c_acctbal,  n_name,  c_address,  c_phone,  c_comment from  customer,  orders,  lineitem,  nation where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate >= date '1993-08-01'  and o_orderdate < date '1993-08-01' + interval '3' month  and l_returnflag = 'R'  and c_nationkey = n_nationkey group by  c_custkey,  c_name,  c_acctbal,  c_phone,  n_name,  c_address,  c_comment order by  revenue desc limit 20;
select l_shipinstruct, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 76745 AND ps_comment = 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND l_shipmode = 'REG AIR' AND p_retailprice <= 1294.25
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%steel%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '69' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'ROMANIA' and n2.n_name = 'RUSSIA')     or (n1.n_name = 'RUSSIA' and n2.n_name = 'ROMANIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 33  and p_type like '%COPPER'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#32'  and p_type not like 'STANDARD POLISHED%'  and p_size in (47, 7, 46, 2, 50, 30, 19, 36)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select c_nationkey, o_custkey, r_name, c_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where o_orderdate = '1993-09-09' AND n_regionkey < 2 AND o_comment = 'ggle. carefully ironic ideas' order by c_nationkey ASC, r_name DESC, c_name ASC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('SHIP', 'REG AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'MAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT o_orderpriority FROM orders WHERE o_orderdate >= '1995-09-26' AND o_shippriority > 0 AND o_clerk >= 'Clerk#000000621' AND o_orderkey > 702946 AND o_orderstatus >= 'F' ORDER BY o_orderpriority ASC
select l_commitdate, ps_availqty from lineitem, partsupp where l_linestatus = 'F' AND l_orderkey < 56675 AND l_tax < 0.05 AND l_extendedprice = 4460.36
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'cyan%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1997-01-01'      and l_shipdate < date '1997-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'RUSSIA' order by  s_name ;
select  o_year,  sum(case   when nation = 'INDIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL BURNISHED STEEL'  ) as all_nations group by  o_year order by  o_year ;
select l_extendedprice, o_totalprice from lineitem, orders where l_linestatus >= 'F' AND o_totalprice = 75731.24 AND o_orderstatus = 'O' AND l_suppkey = 6963
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('SHIP', 'REG AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('SHIP', 'FOB')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT p_name, ps_availqty FROM partsupp JOIN part ON p_partkey = ps_partkey WHERE p_name < 'rose goldenrod azure lavender saddle' AND p_brand > 'Brand#25' AND ps_partkey < 65143 AND ps_comment > 'arefully quiet instructions wake along the slyly'
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#42'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 2 and l_quantity <= 2 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#52'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 11 and l_quantity <= 11 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#14'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 28 and l_quantity <= 28 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT c_acctbal, o_orderkey, n_nationkey FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE o_clerk = 'Clerk#000000898' AND c_phone < '31-508-135-3622' AND o_comment > 'silent requests. regular pinto be' ORDER BY n_nationkey DESC, o_orderkey DESC, c_acctbal DESC
SELECT s_phone, ps_availqty FROM supplier, partsupp WHERE ps_availqty <= 7011 AND s_acctbal >= 464.68 AND s_phone = '23-970-853-1710' AND s_address = 'NxR4B,oub4GdMpx8lVaR' ORDER BY s_phone ASC, ps_availqty ASC
select  o_year,  sum(case   when nation = 'SAUDI ARABIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'STANDARD BRUSHED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select p_mfgr, ps_availqty, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 9188 AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 136593 group by p_mfgr, ps_availqty having min(p_container) = 'JUMBO CASE'
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('25', '18', '29', '32', '24', '12', '34')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('25', '18', '29', '32', '24', '12', '34')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'INDIA' and n2.n_name = 'JORDAN')     or (n1.n_name = 'JORDAN' and n2.n_name = 'INDIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'rosy%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1996-01-01'      and l_shipdate < date '1996-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'IRAN' order by  s_name ;
select c_name, c_nationkey, n_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where o_comment = 'ions haggle carefully above the ironic realms. regula' AND o_orderdate < '1994-06-14' AND o_custkey = 100694 order by c_nationkey ASC, n_regionkey DESC, r_name ASC
select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'O' AND p_type = 'STANDARD BRUSHED STEEL' AND l_commitdate = '1994-07-29' AND l_orderkey < 4693120 AND ps_comment > 'thes haggle carefully. stealthy deposits cajole about the final, express dolphins.' order by ps_partkey DESC, p_name ASC
SELECT n_name, c_address, o_orderstatus FROM nation, customer, orders WHERE c_address <= 'dfsCDFGpDdYSjLHIcaO2 X9W8YwYLB7XlF' AND c_name = 'Customer#000131107' AND o_orderstatus > 'P' ORDER BY n_name DESC
SELECT p_name, ps_availqty, MAX(p_container) FROM partsupp JOIN part ON p_partkey = ps_partkey WHERE p_size >= 2 AND p_partkey > 57787 AND ps_supplycost > 220.03 AND ps_availqty = 2174 GROUP BY p_name, ps_availqty
select l_linestatus, o_totalprice from lineitem, orders where o_totalprice >= 68621.84 AND o_orderstatus = 'P' AND l_suppkey = 8624 AND l_extendedprice = 28681.83
SELECT o_orderkey, l_orderkey, c_comment FROM customer JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE l_returnflag <> 'N' AND l_tax > 0.05 AND c_phone >= '13-268-469-1359' AND o_orderdate = '1995-08-03' ORDER BY l_orderkey DESC, c_comment ASC, o_orderkey DESC
select ps_partkey, ps_comment, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where l_extendedprice = 25969.03 AND l_partkey = 141608 AND l_returnflag >= 'N' AND l_shipinstruct = 'NONE'
select ps_partkey, l_comment, l_shipinstruct from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where s_name = 'Supplier#000006837' AND s_name = 'Supplier#000000551' AND s_suppkey = 1933 order by ps_partkey DESC, l_comment ASC
select o_custkey, o_totalprice from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 168844.46 AND l_receiptdate > '1994-08-25' AND l_tax > 0.02 order by o_custkey DESC, o_totalprice ASC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#54'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 4 and l_quantity <= 4 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#23'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 19 and l_quantity <= 19 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#41'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 30 and l_quantity <= 30 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('23', '30', '28', '21', '19', '31', '25')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('23', '30', '28', '21', '19', '31', '25')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'TRUCK')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT l_suppkey, o_clerk, MIN(l_shipinstruct) FROM orders JOIN lineitem ON l_orderkey = o_orderkey WHERE o_clerk = 'Clerk#000000934' AND l_partkey >= 147429 AND o_orderkey >= 3241411 GROUP BY l_suppkey, o_clerk HAVING MIN(l_shipinstruct) <= 'COLLECT COD' ORDER BY MIN(l_shipinstruct) ASC
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1996-01-01'  and l_shipdate < date '1996-01-01' + interval '1' year  and l_discount between 0.03 - 0.01 and 0.03 + 0.01  and l_quantity < 24 ;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '97' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#14'  and p_container = 'WRAP PACK'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT p_partkey, ps_availqty FROM part, partsupp WHERE p_name > 'chiffon metallic orange turquoise snow' AND ps_supplycost < 520.94 AND ps_partkey <> 89084 AND ps_availqty = 295 ORDER BY ps_availqty ASC
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'N' AND p_brand > 'Brand#23' AND ps_supplycost = 334.23 AND l_linenumber = 7 order by p_mfgr DESC, l_linenumber ASC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'MAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1994-01-01'  and l_receiptdate < date '1994-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'dark%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1995-01-01'      and l_shipdate < date '1995-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'GERMANY' order by  s_name ;
select  o_year,  sum(case   when nation = 'CHINA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'ECONOMY BRUSHED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'ALGERIA' and n2.n_name = 'EGYPT')     or (n1.n_name = 'EGYPT' and n2.n_name = 'ALGERIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 3  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AFRICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AFRICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT p_type, ps_comment, s_phone FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN supplier ON s_suppkey = ps_suppkey WHERE ps_partkey >= 152695 AND ps_comment < 'wake carefully silently final packages. carefully even deposits use special, re' AND s_address > 'CD6mwylfDc2CrjrEKzSbK9LbGEC9irn' ORDER BY ps_comment ASC
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'CHINA' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'CHINA'   ) order by  value desc ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#33'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 5 and l_quantity <= 5 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#34'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 14 and l_quantity <= 14 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#32'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 22 and l_quantity <= 22 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select c_acctbal, o_custkey, n_nationkey, o_clerk from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000060617' AND o_orderdate < '1995-01-28' AND o_comment = 'ggle. carefully ironic ideas' order by o_custkey ASC, c_acctbal DESC, o_clerk ASC
SELECT o_orderdate, c_name, n_comment, l_comment, MAX(n_name) FROM lineitem JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey WHERE l_linenumber = 4 AND c_custkey <= 42930 GROUP BY o_orderdate, c_name, n_comment, l_comment ORDER BY MAX(n_name) DESC
select s_comment, p_retailprice, ps_comment, r_comment, r_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where ps_comment < 'xpress dinos. carefully final pinto beans according to the accounts will have to affix carefully even ideas. silent, unusual packages boost! regular deposi' AND ps_availqty = 8560 AND n_comment = 'al foxes promise slyly according to the regular accounts. bold requests alon'
select p_mfgr, p_retailprice, ps_availqty from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipdate > '1992-05-24' AND l_returnflag > 'A' AND ps_supplycost = 334.23 AND l_linenumber = 7 order by p_mfgr DESC, ps_availqty ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 36  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AFRICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AFRICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1997-01-01'  and l_shipdate < date '1997-01-01' + interval '1' month ;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '92' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select ps_availqty, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1995-11-14' AND l_partkey = 9605 AND l_returnflag >= 'R' AND l_shipinstruct = 'TAKE BACK RETURN'
select ps_suppkey, s_comment, r_regionkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 8448 group by n_regionkey, s_comment, r_regionkey, ps_suppkey order by ps_suppkey DESC, r_regionkey DESC
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'royal%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1993-01-01'      and l_shipdate < date '1993-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'JAPAN' order by  s_name ;
select ps_suppkey, s_comment, r_regionkey, ps_comment, count(s_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 3273 group by ps_suppkey, s_comment, ps_comment, r_regionkey order by ps_suppkey ASC, r_regionkey DESC
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_partkey >= 89084 AND s_comment < 'ular deposits should are express foxes. furiously express excuses haggle busily. furiously' AND ps_availqty <= 9188 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
select c_nationkey, o_custkey, o_orderdate, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name >= 'Customer#000113704' AND o_orderdate < '1995-01-28' AND o_comment = 'ggle. carefully ironic ideas' order by c_nationkey ASC, o_custkey DESC, r_name ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#21'  and p_type not like 'ECONOMY BRUSHED%'  and p_size in (23, 13, 29, 30, 41, 4, 26, 24)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT s_comment, ps_partkey, l_shipmode, MIN(s_name), SUM(ps_partkey) FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey WHERE s_phone = '17-292-821-2297' AND s_name < 'Supplier#000001926' AND l_partkey > 167548 GROUP BY s_comment, ps_partkey, l_shipmode HAVING MIN(s_name) <= 'Supplier#000006418' ORDER BY SUM(ps_partkey) DESC, MIN(s_name) ASC
SELECT s_acctbal, ps_suppkey FROM partsupp JOIN supplier ON s_suppkey = ps_suppkey WHERE ps_supplycost = 739.78 AND s_name >= 'Supplier#000004391' AND ps_comment > 'inal ideas integrate furiously furiously bold platelets. furiously final pearls impress among the car' AND ps_partkey <= 136593 ORDER BY s_acctbal ASC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'IRAN' and n2.n_name = 'MOROCCO')     or (n1.n_name = 'MOROCCO' and n2.n_name = 'IRAN')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  o_year,  sum(case   when nation = 'JAPAN' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'ECONOMY ANODIZED BRASS'  ) as all_nations group by  o_year order by  o_year ;
SELECT ps_availqty, p_name FROM partsupp, part WHERE p_partkey < 126438 AND p_brand < 'Brand#54' AND p_retailprice = 1900.84 AND p_name > 'yellow honeydew cornsilk peach wheat'
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 37  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '96' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select s_name, s_phone, s_comment, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where ps_partkey = 168525 AND l_shipmode < 'RAIL' AND l_partkey > 167548 group by s_comment, s_phone, s_name having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select  o_year,  sum(case   when nation = 'UNITED KINGDOM' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'LARGE ANODIZED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'FURNITURE'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-21'  and l_shipdate > date '1995-03-21' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  c_count,  count(*) as custdist from  (   select    c_custkey,    count(o_orderkey)   from    customer left outer join orders on     c_custkey = o_custkey     and o_comment not like '%pending%requests%'   group by    c_custkey  ) as c_orders (c_custkey, c_count) group by  c_count order by  custdist desc,  c_count desc ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'BUILDING'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-06'  and l_shipdate > date '1995-03-06' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('16', '33', '26', '31', '14', '32', '19')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('16', '33', '26', '31', '14', '32', '19')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  o_year,  sum(case   when nation = 'IRAN' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM BURNISHED BRASS'  ) as all_nations group by  o_year order by  o_year ;
SELECT l_shipmode, ps_availqty FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_commitdate = '1995-11-21' AND l_shipdate <> '1994-05-24' AND l_quantity <> 2.0 AND ps_supplycost <= 57.43 AND l_shipmode < 'MAIL' ORDER BY l_shipmode ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#41'  and p_type not like 'STANDARD BURNISHED%'  and p_size in (22, 44, 43, 6, 13, 19, 20, 49)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT o_orderpriority, c_acctbal FROM customer, orders WHERE o_orderpriority < '4-NOT SPECIFIED' AND c_address <= '1uItjXUxfvnTPgCh' AND c_phone > '13-675-522-6406' AND o_shippriority > 0
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('31', '20', '10', '30', '15', '18', '24')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('31', '20', '10', '30', '15', '18', '24')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#43'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#15'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 30 and l_quantity <= 30 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select ps_availqty, s_name, p_mfgr, n_name, r_comment from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where ps_comment < 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND n_comment = 'ously. final, express gifts cajole a' AND r_name = 'EUROPE'
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#55'  and p_type not like 'PROMO PLATED%'  and p_size in (18, 11, 43, 33, 19, 40, 45, 29)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '85' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 44  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  n_name,  sum(l_extendedprice * (1 - l_discount)) as revenue from  customer,  orders,  lineitem,  supplier,  nation,  region where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and l_suppkey = s_suppkey  and c_nationkey = s_nationkey  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and o_orderdate >= date '1995-01-01'  and o_orderdate < date '1995-01-01' + interval '1' year group by  n_name order by  revenue desc ;
SELECT p_type, ps_availqty, MAX(p_comment), MAX(ps_supplycost) FROM partsupp JOIN part ON p_partkey = ps_partkey WHERE p_container = 'JUMBO DRUM' AND p_name < 'snow bisque rosy pink pale' AND ps_partkey > 65143 GROUP BY p_type, ps_availqty ORDER BY MAX(p_comment) DESC
SELECT p_mfgr, l_linenumber, ps_comment FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_returnflag > 'N' AND p_brand > 'Brand#23' AND ps_supplycost <> 334.23 AND l_linenumber = 7 ORDER BY p_mfgr DESC, l_linenumber ASC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('MAIL', 'TRUCK')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select l_partkey, s_comment, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where ps_partkey = 138335 AND s_name < 'Supplier#000001926' AND s_phone > '27-639-321-9156' group by s_comment, l_shipmode, l_partkey having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
select p_container, ps_availqty, min(p_mfgr) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 4783 AND p_mfgr = 'Manufacturer#2' AND ps_partkey <= 133788 group by p_container, ps_availqty having min(p_mfgr) = 'Manufacturer#3'
select  c_count,  count(*) as custdist from  (   select    c_custkey,    count(o_orderkey)   from    customer left outer join orders on     c_custkey = o_custkey     and o_comment not like '%express%accounts%'   group by    c_custkey  ) as c_orders (c_custkey, c_count) group by  c_count order by  custdist desc,  c_count desc ;
select c_nationkey, o_orderdate, o_comment, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where n_regionkey = 1 AND c_name < 'Customer#000004284' AND o_custkey = 99901 order by c_nationkey ASC, o_orderdate DESC, r_name ASC
select l_linestatus, l_suppkey from lineitem, orders where o_orderstatus >= 'O' AND l_extendedprice = 35621.76 AND o_totalprice = 211151.4 AND o_totalprice = 112609.58
SELECT p_size, ps_supplycost FROM part JOIN partsupp ON ps_partkey = p_partkey WHERE ps_comment <> 's. carefully regular instructions hang furiously slyly pending accounts. bold packages' AND p_name > 'rosy aquamarine purple sky violet' AND ps_availqty = 9854 AND ps_partkey > 120117 ORDER BY ps_supplycost ASC
SELECT p_brand, ps_partkey FROM part JOIN partsupp ON ps_partkey = p_partkey WHERE ps_availqty <> 6331 AND ps_partkey >= 188984 AND p_size < 20 AND p_mfgr <= 'Manufacturer#3' AND ps_supplycost <> 628.53 AND p_comment > 'riously bold d'
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#51'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 4 and l_quantity <= 4 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 11 and l_quantity <= 11 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#11'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 29 and l_quantity <= 29 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'MACHINERY'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-01'  and l_shipdate > date '1995-03-01' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'saddle%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1993-01-01'      and l_shipdate < date '1993-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'KENYA' order by  s_name ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'FURNITURE'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-30'  and l_shipdate > date '1995-03-30' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
SELECT l_shipmode, ps_partkey FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_comment < 'riously unusual acco' AND l_suppkey = 2785 AND l_linenumber <> 4 AND l_returnflag <= 'A'
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '104' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'MACHINERY'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-13'  and l_shipdate > date '1995-03-13' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
SELECT o_custkey FROM orders WHERE o_orderdate <= '1993-08-21' AND o_orderstatus <= 'O' AND o_shippriority >= 0 AND o_orderkey <> 1472992 ORDER BY o_custkey ASC
select  s_name,  count(*) as numwait from  supplier,  lineitem l1,  orders,  nation where  s_suppkey = l1.l_suppkey  and o_orderkey = l1.l_orderkey  and o_orderstatus = 'F'  and l1.l_receiptdate > l1.l_commitdate  and exists (   select    *   from    lineitem l2   where    l2.l_orderkey = l1.l_orderkey    and l2.l_suppkey <> l1.l_suppkey  )  and not exists (   select    *   from    lineitem l3   where    l3.l_orderkey = l1.l_orderkey    and l3.l_suppkey <> l1.l_suppkey    and l3.l_receiptdate > l3.l_commitdate  )  and s_nationkey = n_nationkey  and n_name = 'IRAQ' group by  s_name order by  numwait desc,  s_name limit 100;
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 9354 AND ps_suppkey < 4793 AND ps_partkey <= 173618 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
SELECT o_orderstatus, l_orderkey, ps_supplycost FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE l_extendedprice > 31446.03 AND l_partkey <> 152696 AND l_linestatus < 'F' ORDER BY l_orderkey ASC, ps_supplycost ASC, o_orderstatus DESC
SELECT l_commitdate, ps_supplycost FROM lineitem, partsupp WHERE l_linenumber > 6 AND l_discount = 0.08 AND ps_availqty = 9160 AND l_linestatus <= 'F'
select  o_year,  sum(case   when nation = 'IRAQ' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL POLISHED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select l_commitdate, ps_availqty from lineitem, partsupp where l_linestatus = 'F' AND l_orderkey < 56675 AND l_tax < 0.07 AND l_extendedprice = 41364.0
SELECT ps_availqty, p_mfgr FROM partsupp, part WHERE ps_supplycost = 738.31 AND p_type > 'SMALL POLISHED STEEL' AND ps_availqty <> 1842 AND ps_suppkey > 7455
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'REG AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#54'  and p_type not like 'ECONOMY BRUSHED%'  and p_size in (22, 10, 19, 14, 49, 40, 42, 45)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT l_suppkey, ps_suppkey FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_extendedprice <> 27509.72 AND l_shipmode >= 'AIR' AND l_orderkey = 4852774 AND ps_comment < 'ts about the fluffily final pinto beans thrash slyly according to the furiously ironic foxes. even packages sleep across the ironic asymptotes. pending f'
SELECT l_shipmode, o_shippriority, c_nationkey, MAX(o_custkey) FROM customer JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE l_shipinstruct >= 'NONE' AND c_mktsegment >= 'BUILDING' AND c_acctbal = 5362.82 GROUP BY l_shipmode, o_shippriority, c_nationkey ORDER BY MAX(o_custkey) DESC
SELECT c_acctbal, n_nationkey, s_nationkey FROM customer JOIN nation ON n_nationkey = c_nationkey JOIN supplier ON s_nationkey = n_nationkey WHERE c_phone > '17-265-877-1490' AND s_acctbal <= 4974.33 AND n_comment < 'al foxes promise slyly according to the regular accounts. bold requests alon' ORDER BY n_nationkey ASC, c_acctbal DESC, s_nationkey ASC
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'FURNITURE'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-31'  and l_shipdate > date '1995-03-31' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
SELECT o_totalprice, n_comment, c_name FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE c_name <> 'Customer#000101062' AND o_orderdate >= '1995-12-06' AND o_comment > 'ely silent theodolites boost slyly. furi' AND o_orderpriority = '4-NOT SPECIFIED' AND o_orderstatus = 'P'
select p_mfgr, l_returnflag, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where p_brand > 'Brand#44' AND ps_supplycost > 738.31 AND l_linenumber = 5 AND l_linenumber = 3 order by p_mfgr DESC, ps_comment ASC
SELECT l_linestatus, o_comment FROM orders JOIN lineitem ON l_orderkey = o_orderkey WHERE l_extendedprice > 31446.03 AND o_orderkey <= 1783811 AND l_tax = 0.05 AND l_quantity >= 24.0 AND l_shipdate > '1993-02-28' AND l_orderkey > 3911749
SELECT c_custkey, o_orderdate, n_regionkey FROM orders, customer, nation WHERE o_shippriority < 0 AND c_mktsegment > 'MACHINERY' AND o_comment = 'the requests. carefully ironic deposits hang fluffily package' AND c_address = '1uItjXUxfvnTPgCh' AND c_name > 'Customer#000134672'
select c_custkey, n_regionkey, o_clerk from orders, customer, nation where o_totalprice < 36447.99 AND c_acctbal = 1481.44 AND c_name = 'Customer#000143733' AND c_mktsegment > 'BUILDING' AND o_shippriority < 0
select ps_availqty, o_orderdate, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where l_quantity > 36.0 AND l_partkey = 141608 AND l_returnflag >= 'N' AND l_shipinstruct = 'NONE'
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'MOZAMBIQUE' and n2.n_name = 'CHINA')     or (n1.n_name = 'CHINA' and n2.n_name = 'MOZAMBIQUE')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select p_mfgr, ps_partkey, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 9188 AND p_mfgr = 'Manufacturer#4' AND ps_availqty <= 9312 group by p_mfgr, ps_partkey having min(p_container) = 'SM CASE'
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#54'  and p_type not like 'ECONOMY BURNISHED%'  and p_size in (28, 17, 24, 43, 10, 9, 34, 41)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select l_commitdate, ps_availqty from lineitem, partsupp where l_linestatus = 'F' AND l_orderkey < 56675 AND l_tax < 0.0 AND l_extendedprice = 41364.0
select p_mfgr, ps_comment, ps_supplycost from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where p_brand > 'Brand#35' AND l_linenumber > 4 AND l_returnflag = 'A' AND l_linenumber = 7 order by p_mfgr DESC, ps_comment ASC
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1994-11-01'  and l_shipdate < date '1994-11-01' + interval '1' month ;
SELECT p_name, ps_availqty FROM partsupp, part WHERE p_container <= 'LG CASE' AND p_brand > 'Brand#32' AND ps_comment = 'e carefully pending foxes sleep furiously among the slyly special requests. blithely final req' AND p_type > 'MEDIUM BRUSHED NICKEL' ORDER BY ps_availqty ASC, p_name ASC
select l_shipinstruct, l_discount, l_returnflag from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 69470 AND l_returnflag = 'N' AND l_shipmode = 'SHIP' AND p_retailprice <= 1831.73
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%peach%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'cornflower%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1994-01-01'      and l_shipdate < date '1994-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'ALGERIA' order by  s_name ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('29', '17', '31', '22', '12', '28', '18')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('29', '17', '31', '22', '12', '28', '18')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select p_brand, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linenumber > 5 AND p_mfgr > 'Manufacturer#1' AND ps_supplycost = 334.23 AND l_returnflag = 'R' order by ps_comment DESC, l_linenumber ASC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('AIR', 'MAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select l_commitdate, ps_availqty from lineitem, partsupp where l_linestatus = 'F' AND l_orderkey < 56675 AND l_tax < 0.04 AND l_extendedprice = 17058.56
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#31'  and p_container = 'WRAP CASE'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('30', '24', '11', '18', '33', '12', '17')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('30', '24', '11', '18', '33', '12', '17')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select ps_suppkey, s_comment, r_regionkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 6121 group by ps_suppkey, s_comment, r_regionkey, n_regionkey order by s_comment DESC, r_regionkey DESC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 33  and p_type like '%COPPER'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#11'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 8 and l_quantity <= 8 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#51'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 18 and l_quantity <= 18 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#15'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 26 and l_quantity <= 26 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT o_clerk, s_nationkey, l_shipdate, n_nationkey, ps_availqty FROM nation JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE o_shippriority < 0 AND o_comment <> 'lyly bold instructions. regular packages aga' ORDER BY l_shipdate ASC, ps_availqty ASC, o_clerk DESC, n_nationkey ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('34', '14', '20', '28', '22', '27', '11')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('34', '14', '20', '28', '22', '27', '11')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select l_comment, s_name, l_shipinstruct from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where s_suppkey = 1399 AND ps_partkey = 75919 AND s_name = 'Supplier#000001708' order by l_shipinstruct DESC, s_name ASC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#51'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 3 and l_quantity <= 3 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#51'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 17 and l_quantity <= 17 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#53'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 30 and l_quantity <= 30 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select ps_availqty, o_orderpriority, l_partkey from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1995-09-02' AND l_returnflag = 'R' AND l_returnflag >= 'N' AND l_shipinstruct = 'NONE'
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'NONE' AND s_name = 'Supplier#000007968' AND s_suppkey = 6024 order by ps_partkey DESC, s_name ASC
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 6331 AND ps_supplycost = 110.61 AND ps_partkey <= 173618 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'BRAZIL' and n2.n_name = 'CANADA')     or (n1.n_name = 'CANADA' and n2.n_name = 'BRAZIL')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  o_year,  sum(case   when nation = 'INDONESIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM BRUSHED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select s_phone, ps_suppkey, n_nationkey from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey where n_regionkey <= 3 AND n_comment >= 'refully final requests. regular, ironi' AND ps_supplycost > 835.16 order by s_phone ASC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  s_name,  count(*) as numwait from  supplier,  lineitem l1,  orders,  nation where  s_suppkey = l1.l_suppkey  and o_orderkey = l1.l_orderkey  and o_orderstatus = 'F'  and l1.l_receiptdate > l1.l_commitdate  and exists (   select    *   from    lineitem l2   where    l2.l_orderkey = l1.l_orderkey    and l2.l_suppkey <> l1.l_suppkey  )  and not exists (   select    *   from    lineitem l3   where    l3.l_orderkey = l1.l_orderkey    and l3.l_suppkey <> l1.l_suppkey    and l3.l_receiptdate > l3.l_commitdate  )  and s_nationkey = n_nationkey  and n_name = 'KENYA' group by  s_name order by  numwait desc,  s_name limit 100;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 9 and l_quantity <= 9 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#42'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 13 and l_quantity <= 13 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#12'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 21 and l_quantity <= 21 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select l_orderkey, l_quantity, p_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_partkey >= 98953 AND p_type = 'STANDARD BRUSHED STEEL' AND l_commitdate = '1998-10-10' AND l_orderkey < 2618950 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by p_comment DESC, l_quantity ASC
select  n_name,  sum(l_extendedprice * (1 - l_discount)) as revenue from  customer,  orders,  lineitem,  supplier,  nation,  region where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and l_suppkey = s_suppkey  and c_nationkey = s_nationkey  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and o_orderdate >= date '1993-01-01'  and o_orderdate < date '1993-01-01' + interval '1' year group by  n_name order by  revenue desc ;
SELECT s_address, ps_comment FROM supplier, partsupp WHERE ps_partkey > 142881 AND s_nationkey = 14 AND s_acctbal >= 464.68 AND ps_availqty < 9324 AND s_phone <= '23-233-827-5081' AND ps_supplycost <= 214.27
select r_name, s_name, p_mfgr, r_comment, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where n_comment < 'rns. blithely bold courts among the closely regular packages use furiously bold platelets?' AND ps_availqty = 8560 AND ps_comment = 'bold requests are carefully thin foxes. express, ironic hockey players ar'
select r_comment, n_name, ps_availqty, r_name, ps_comment from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where p_mfgr < 'Manufacturer#2' AND n_comment = 'al foxes promise slyly according to the regular accounts. bold requests alon' AND s_name = 'Supplier#000001127'
select c_nationkey, o_orderstatus, n_comment from orders, customer, nation where o_totalprice < 36447.99 AND c_acctbal = 3320.06 AND c_name = 'Customer#000143733' AND c_mktsegment > 'BUILDING' AND o_shippriority < 0
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('REG AIR', 'RAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select o_orderkey, o_orderstatus, n_comment from orders, customer, nation where o_totalprice = 48442.69 AND n_nationkey = 3 AND c_name = 'Customer#000143733' AND c_mktsegment > 'BUILDING' AND o_shippriority < 0
SELECT l_shipmode, ps_comment, s_nationkey FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_linenumber = 5 AND l_extendedprice > 21651.14 AND l_returnflag > 'R' ORDER BY ps_comment DESC, s_nationkey ASC, l_shipmode ASC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('REG AIR', 'TRUCK')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1993-01-01'  and l_receiptdate < date '1993-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%ghost%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
SELECT c_mktsegment, o_comment, n_comment FROM orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey WHERE c_acctbal = 2827.03 AND o_custkey = 82165 AND o_shippriority <= 0 ORDER BY n_comment ASC, o_comment ASC, c_mktsegment DESC
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'firebrick%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1996-01-01'      and l_shipdate < date '1996-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'MOROCCO' order by  s_name ;
SELECT c_comment, ps_supplycost, n_regionkey, s_name, l_comment FROM customer JOIN nation ON n_nationkey = c_nationkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE c_nationkey >= 13 AND c_name = 'Customer#000019378' AND c_acctbal <= 6424.57 AND s_nationkey <> 11
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#11'  and p_type not like 'SMALL BRUSHED%'  and p_size in (21, 26, 8, 29, 31, 9, 14, 5)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'sky%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1995-01-01'      and l_shipdate < date '1995-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'UNITED STATES' order by  s_name ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'dim%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1995-01-01'      and l_shipdate < date '1995-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'BRAZIL' order by  s_name ;
SELECT o_shippriority FROM orders WHERE o_clerk <= 'Clerk#000000995' AND o_orderstatus <> 'O' AND o_totalprice <> 25079.15 AND o_comment <> 'tions. blithely ironic requests slee' ORDER BY o_shippriority DESC
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1993-01-01'  and l_shipdate < date '1993-01-01' + interval '1' year  and l_discount between 0.08 - 0.01 and 0.08 + 0.01  and l_quantity < 24 ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'JORDAN' and n2.n_name = 'IRAN')     or (n1.n_name = 'IRAN' and n2.n_name = 'JORDAN')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
SELECT l_suppkey FROM lineitem WHERE l_shipdate = '1992-03-09' AND l_tax = 0.01 AND l_orderkey >= 1744545 AND l_linenumber >= 1 AND l_shipinstruct >= 'COLLECT COD' AND l_shipmode < 'SHIP' ORDER BY l_suppkey ASC
select l_comment, s_name, l_shipmode from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'NONE' AND s_name <= 'Supplier#000000551' AND s_suppkey = 1561 order by s_name DESC, l_shipmode ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#44'  and p_type not like 'LARGE ANODIZED%'  and p_size in (46, 6, 10, 20, 27, 37, 29, 7)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('19', '27', '12', '30', '23', '15', '24')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('19', '27', '12', '30', '23', '15', '24')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('15', '18', '31', '33', '32', '28', '16')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('15', '18', '31', '33', '32', '28', '16')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select ps_comment, ps_availqty, n_name from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey where s_nationkey <= 23 AND n_comment >= 'eans boost carefully special requests. accounts are. carefull' AND ps_partkey >= 3362 order by ps_availqty ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('31', '27', '10', '20', '11', '28', '15')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('31', '27', '10', '20', '11', '28', '15')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('18', '34', '12', '20', '15', '25', '28')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('18', '34', '12', '20', '15', '25', '28')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT l_suppkey, MAX(l_receiptdate), COUNT(l_quantity) FROM lineitem WHERE l_comment <> 'ideas nag furiously carefully ev' AND l_receiptdate <= '1996-01-06' AND l_shipdate = '1993-05-13' AND l_returnflag >= 'R' GROUP BY l_suppkey ORDER BY l_suppkey ASC
select l_linestatus, o_totalprice from lineitem, orders where o_totalprice >= 68621.84 AND o_orderstatus = 'F' AND l_suppkey = 164 AND l_extendedprice = 3615.8
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 15  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select c_mktsegment, n_comment, o_totalprice from orders, customer, nation where o_orderstatus < 'P' AND c_nationkey = 22 AND c_name = 'Customer#000143733' AND o_shippriority > 0 AND c_acctbal < 1332.17
select l_comment, s_name, s_suppkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where ps_partkey = 5804 AND s_name = 'Supplier#000000551' AND l_shipinstruct = 'TAKE BACK RETURN' order by s_name DESC, s_suppkey ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 32  and p_type like '%BRASS'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT ps_supplycost, o_clerk, l_partkey FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE o_orderdate > '1994-04-04' AND l_receiptdate <= '1992-03-14' AND l_shipmode > 'REG AIR' ORDER BY l_partkey DESC, ps_supplycost DESC
SELECT r_comment, o_orderkey, c_name, n_regionkey FROM orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey WHERE o_orderpriority <= '1-URGENT' AND r_regionkey = 2 AND c_comment <> 'r the regular, bold dolphins use carefully fluffily dogged accounts. carefully even t' ORDER BY o_orderkey ASC, c_name DESC, r_comment DESC
select n_regionkey, ps_availqty, s_suppkey from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey where ps_availqty < 2301 AND n_comment >= 'eans boost carefully special requests. accounts are. carefull' AND n_nationkey >= 24 order by ps_availqty ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 50  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  o_year,  sum(case   when nation = 'CHINA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'STANDARD BRUSHED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#34'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 11 and l_quantity <= 11 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 30 and l_quantity <= 30 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#34'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 2 and l_quantity <= 2 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#33'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 13 and l_quantity <= 13 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#23'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 30 and l_quantity <= 30 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'FRANCE' and n2.n_name = 'MOROCCO')     or (n1.n_name = 'MOROCCO' and n2.n_name = 'FRANCE')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select r_name, o_custkey, o_orderdate, n_regionkey from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000143733' AND c_nationkey < 12 AND o_comment = 'ggle. carefully ironic ideas' order by r_name ASC, n_regionkey DESC, o_orderdate ASC
select  n_name,  sum(l_extendedprice * (1 - l_discount)) as revenue from  customer,  orders,  lineitem,  supplier,  nation,  region where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and l_suppkey = s_suppkey  and c_nationkey = s_nationkey  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and o_orderdate >= date '1994-01-01'  and o_orderdate < date '1994-01-01' + interval '1' year group by  n_name order by  revenue desc ;
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1993-01-01'  and l_shipdate < date '1993-01-01' + interval '1' year  and l_discount between 0.05 - 0.01 and 0.05 + 0.01  and l_quantity < 24 ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'FURNITURE'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-04'  and l_shipdate > date '1995-03-04' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('31', '25', '22', '10', '24', '15', '23')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('31', '25', '22', '10', '24', '15', '23')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT l_returnflag, ps_partkey FROM partsupp, lineitem WHERE ps_availqty <= 4781 AND l_discount >= 0.01 AND l_orderkey > 4852774 AND l_linenumber > 7
select s_name, l_returnflag, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct <= 'COLLECT COD' AND s_name = 'Supplier#000000551' AND s_suppkey = 1933 order by ps_partkey DESC, s_name ASC
SELECT ps_comment, p_name FROM partsupp JOIN part ON p_partkey = ps_partkey WHERE p_type > 'LARGE POLISHED TIN' AND ps_availqty < 6827 AND p_mfgr >= 'Manufacturer#2' AND p_partkey > 185599 ORDER BY ps_comment ASC, p_name DESC
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%sandy%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select p_mfgr, ps_availqty, min(ps_availqty) from part JOIN partsupp ON ps_partkey = p_partkey where p_container = 'SM CAN' AND p_mfgr = 'Manufacturer#3' AND ps_partkey <= 80483 group by p_mfgr, ps_availqty having min(ps_availqty) = 2301
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'HOUSEHOLD' AND o_orderkey = 1093635 AND o_custkey < 9136 AND o_orderdate < '1997-03-17'
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 9  and p_type like '%BRASS'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select l_shipinstruct, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 83504 AND ps_comment = 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND l_shipmode = 'TRUCK' AND p_retailprice <= 1831.73
select  o_year,  sum(case   when nation = 'FRANCE' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'STANDARD BRUSHED TIN'  ) as all_nations group by  o_year order by  o_year ;
select o_totalprice, o_orderpriority from orders, lineitem where o_totalprice <= 28177.04 AND o_custkey = 10171 AND l_receiptdate > '1996-02-15' AND l_tax > 0.02 order by o_totalprice DESC, o_orderpriority ASC
