select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'UNITED KINGDOM' and n2.n_name = 'UNITED STATES')     or (n1.n_name = 'UNITED STATES' and n2.n_name = 'UNITED KINGDOM')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
SELECT o_orderdate FROM orders WHERE o_orderdate < '1995-11-01' AND o_comment > 'y even decoys serve fluffily. pending, pen' AND o_clerk <= 'Clerk#000000882' AND o_custkey > 112039 AND o_totalprice <= 63471.44
SELECT c_phone, o_comment, n_comment FROM orders, customer, nation WHERE o_orderkey <= 4203043 AND o_totalprice <= 44719.4 AND c_address <= 'nYdOZgtFmXid' AND c_acctbal = 3135.07 AND n_name >= 'ARGENTINA'
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#32'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 1 and l_quantity <= 1 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#45'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 19 and l_quantity <= 19 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#42'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 27 and l_quantity <= 27 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT c_acctbal, l_orderkey, o_clerk, MIN(l_partkey) FROM lineitem JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE c_mktsegment <= 'HOUSEHOLD' AND l_receiptdate = '1993-11-30' AND l_linenumber < 2 AND c_address <> '57BpVhzaCndKK3' GROUP BY c_acctbal, l_orderkey, o_clerk ORDER BY MIN(l_partkey) ASC
SELECT c_phone, o_comment FROM orders JOIN customer ON c_custkey = o_custkey WHERE o_clerk <> 'Clerk#000000898' AND o_orderdate <= '1995-11-01' AND c_mktsegment <= 'BUILDING' AND c_comment = 'nding dependencies detect quickly furiously even instructions. silent, final dolphins haggle furious'
SELECT ps_comment FROM partsupp WHERE ps_comment <= 'ual requests sleep carefully. fluffily pending multipl' AND ps_availqty <> 6224 AND ps_supplycost > 797.15 AND ps_partkey >= 59366 AND ps_suppkey > 1229
select  o_year,  sum(case   when nation = 'BRAZIL' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'ECONOMY POLISHED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('AIR', 'FOB')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 39  and p_type like '%COPPER'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#14'  and p_type not like 'MEDIUM BRUSHED%'  and p_size in (35, 9, 42, 4, 50, 40, 36, 49)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1993-01-01'  and l_shipdate < date '1993-01-01' + interval '1' year  and l_discount between 0.02 - 0.01 and 0.02 + 0.01  and l_quantity < 24 ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'MOZAMBIQUE' and n2.n_name = 'UNITED KINGDOM')     or (n1.n_name = 'UNITED KINGDOM' and n2.n_name = 'MOZAMBIQUE')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select l_shipmode, ps_partkey, l_partkey, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_name = 'Supplier#000004741' AND s_phone < '19-740-622-6170' AND s_comment > 'against the fluffily unusual pinto beans. furiously pending requests should' group by l_partkey, ps_partkey, l_shipmode having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
SELECT l_linestatus, o_orderkey, s_address, ps_supplycost FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE s_name = 'Supplier#000009565' AND l_tax <> 0.06 AND s_phone > '23-451-776-3365'
SELECT o_totalprice FROM orders WHERE o_custkey <= 18518 AND o_orderpriority < '2-HIGH' AND o_orderdate >= '1993-02-17' AND o_comment >= 'inally pending packages sleep along the furiously special' ORDER BY o_totalprice ASC
select ps_availqty, o_orderdate, l_shipinstruct from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where l_returnflag > 'N' AND l_returnflag = 'A' AND l_partkey >= 31126 AND o_orderpriority = '5-LOW'
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'orange%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1996-01-01'      and l_shipdate < date '1996-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'CHINA' order by  s_name ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('REG AIR', 'RAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select ps_availqty, l_partkey, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where l_returnflag > 'R' AND l_returnflag = 'N' AND l_shipinstruct >= 'COLLECT COD' AND o_orderdate = '1998-04-22'
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#25'  and p_container = 'WRAP BAG'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select l_extendedprice, ps_availqty from lineitem, partsupp where l_linestatus = 'O' AND l_orderkey < 5367938 AND l_tax < 0.0 AND l_commitdate = '1993-07-09'
select o_orderdate from orders where o_orderdate = '1997-01-20' AND o_orderstatus <= 'O' AND o_shippriority >= 0 AND o_orderkey = 1472992 order by o_orderdate ASC
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 9048 AND s_comment < 'ic requests nag. blithely regular ideas try to wake quickly eve' AND ps_partkey <= 49795 AND s_nationkey < 2 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
select  o_year,  sum(case   when nation = 'ETHIOPIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AFRICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'ECONOMY BURNISHED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1997-03-01'  and l_shipdate < date '1997-03-01' + interval '1' month ;
SELECT l_linestatus, ps_partkey FROM partsupp, lineitem WHERE l_receiptdate >= '1993-01-19' AND l_linenumber >= 1 AND l_linestatus < 'F' AND l_quantity <= 43.0 AND l_commitdate > '1998-10-10'
SELECT n_name, o_orderkey, c_mktsegment FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE n_name <= 'IRAQ' AND o_shippriority >= 0 AND o_clerk < 'Clerk#000000072' ORDER BY c_mktsegment ASC, n_name ASC
select s_comment, ps_partkey, l_shipmode, min(l_partkey), sum(ps_supplycost) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '12-108-684-2764' AND l_suppkey < 5539 AND ps_comment <= 'against the carefully unusual packages boost about the' group by s_comment, ps_partkey, l_shipmode having min(l_partkey) <= 69559 order by sum(ps_supplycost) DESC, min(l_partkey) ASC
select  o_year,  sum(case   when nation = 'VIETNAM' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM BRUSHED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
SELECT l_partkey FROM lineitem WHERE l_linestatus >= 'O' AND l_commitdate <= '1993-02-28' AND l_discount = 0.04 AND l_extendedprice > 50883.12 ORDER BY l_partkey ASC
select o_orderdate, o_custkey, o_totalprice, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name < 'Customer#000060165' AND c_mktsegment < 'AUTOMOBILE' AND o_comment = 'ggle. carefully ironic ideas' order by o_custkey ASC, o_orderdate DESC, r_name ASC
select  o_year,  sum(case   when nation = 'IRAN' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO BRUSHED BRASS'  ) as all_nations group by  o_year order by  o_year ;
SELECT o_orderstatus, c_comment, l_receiptdate FROM lineitem JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE o_clerk < 'Clerk#000000629' AND l_shipinstruct <> 'COLLECT COD' AND c_acctbal = 1083.06 ORDER BY o_orderstatus ASC, c_comment DESC
SELECT o_clerk, ps_comment, l_quantity FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE ps_comment = 'uffily express instructions. carefully special theodolites are against the final packages. furiously ironic pains sleep quickly about' AND l_extendedprice <= 60231.94 AND l_returnflag <= 'R' AND l_commitdate <= '1995-11-12' AND l_orderkey <> 3911749
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'INDONESIA' and n2.n_name = 'IRAQ')     or (n1.n_name = 'IRAQ' and n2.n_name = 'INDONESIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
SELECT r_regionkey, l_partkey, o_shippriority, c_phone, n_regionkey FROM lineitem JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey WHERE n_name < 'KENYA' AND l_shipmode <> 'TRUCK' AND n_comment < 'l platelets. regular accounts x-ray: unusual, regular acco' ORDER BY l_partkey ASC, r_regionkey DESC
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1994-10-01'  and l_shipdate < date '1994-10-01' + interval '1' month ;
