select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#32'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 4 and l_quantity <= 4 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#11'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 18 and l_quantity <= 18 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#33'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 30 and l_quantity <= 30 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('31', '28', '11', '25', '15', '21', '17')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('31', '28', '11', '25', '15', '21', '17')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT ps_suppkey, s_acctbal, r_comment, n_nationkey FROM partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey WHERE n_name = 'ARGENTINA' AND ps_suppkey < 1229 AND ps_supplycost > 343.83
SELECT l_extendedprice FROM lineitem WHERE l_commitdate = '1996-01-02' AND l_linenumber > 1 AND l_extendedprice < 5144.01 AND l_partkey >= 166867 ORDER BY l_extendedprice ASC
select  o_year,  sum(case   when nation = 'JORDAN' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL BRUSHED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#55'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 9 and l_quantity <= 9 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 11 and l_quantity <= 11 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#13'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 25 and l_quantity <= 25 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT l_quantity, p_name, o_orderstatus, c_custkey, n_regionkey, ps_comment FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE l_commitdate < '1996-03-03' AND o_shippriority <> 0
SELECT o_custkey, l_orderkey, ps_availqty, s_nationkey, SUM(ps_suppkey) FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE s_acctbal <= 3019.76 AND s_name < 'Supplier#000000551' AND l_tax >= 0.04 GROUP BY o_custkey, l_orderkey, ps_availqty, s_nationkey
SELECT o_orderdate, l_comment FROM orders JOIN lineitem ON l_orderkey = o_orderkey WHERE o_clerk > 'Clerk#000000580' AND l_partkey = 182431 AND o_shippriority = 0 AND l_quantity >= 22.0
select  s_name,  count(*) as numwait from  supplier,  lineitem l1,  orders,  nation where  s_suppkey = l1.l_suppkey  and o_orderkey = l1.l_orderkey  and o_orderstatus = 'F'  and l1.l_receiptdate > l1.l_commitdate  and exists (   select    *   from    lineitem l2   where    l2.l_orderkey = l1.l_orderkey    and l2.l_suppkey <> l1.l_suppkey  )  and not exists (   select    *   from    lineitem l3   where    l3.l_orderkey = l1.l_orderkey    and l3.l_suppkey <> l1.l_suppkey    and l3.l_receiptdate > l3.l_commitdate  )  and s_nationkey = n_nationkey  and n_name = 'IRAN' group by  s_name order by  numwait desc,  s_name limit 100;
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1995-01-01'  and o_orderdate < date '1995-01-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select l_orderkey, l_commitdate, p_type from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'O' AND l_orderkey = 5829413 AND p_name = 'deep cornflower dim yellow lace' AND ps_partkey < 5023 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by l_orderkey DESC, p_type ASC
select  o_year,  sum(case   when nation = 'VIETNAM' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'STANDARD ANODIZED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1995-04-01'  and l_shipdate < date '1995-04-01' + interval '1' month ;
select p_brand, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_extendedprice = 9235.59 AND l_shipdate > '1995-08-12' AND l_shipmode = 'SHIP' AND p_retailprice <= 1831.73
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('11', '13', '33', '30', '31', '26', '22')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('11', '13', '33', '30', '31', '26', '22')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT l_tax FROM lineitem WHERE l_discount < 0.08 AND l_linestatus <= 'F' AND l_partkey = 47918 AND l_linenumber <= 4 AND l_comment <= 'ies are about the blithely even request' ORDER BY l_tax DESC
SELECT ps_partkey, l_partkey, o_totalprice, c_name, MAX(ps_suppkey) FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE l_partkey <> 131411 AND l_receiptdate = '1998-04-25' GROUP BY ps_partkey, l_partkey, o_totalprice, c_name ORDER BY o_totalprice ASC
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'BUILDING'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-05'  and l_shipdate > date '1995-03-05' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select ps_comment, s_name, p_mfgr, r_comment, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where r_name < 'AMERICA' AND ps_availqty = 6331 AND n_comment = 'al foxes promise slyly according to the regular accounts. bold requests alon'
select s_comment, ps_partkey, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000001926' AND l_partkey > 167548 group by s_comment, ps_partkey, l_shipmode having min(s_name) <= 'Supplier#000001926' order by sum(ps_partkey) DESC, min(s_name) ASC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('AIR', 'RAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select s_comment, ps_partkey, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000004150' AND l_partkey > 92630 group by s_comment, ps_partkey, l_shipmode having min(s_name) <= 'Supplier#000006042' order by sum(ps_partkey) DESC, min(s_name) ASC
select p_mfgr, l_linenumber, l_discount from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'F' AND p_container > 'WRAP PACK' AND ps_supplycost = 334.23 AND l_linenumber = 7 order by p_mfgr DESC, l_linenumber ASC
select p_mfgr, l_linenumber, ps_supplycost from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'A' AND p_brand > 'Brand#23' AND ps_comment = 'luffily. furiously special pinto beans nag furiously? carefully pending requests sleep carefully. ironic accounts h' AND l_linenumber = 4 order by p_mfgr DESC, l_linenumber ASC
SELECT l_shipmode, p_name, ps_suppkey FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE p_partkey >= 173355 AND l_linestatus > 'F' AND l_commitdate = '1993-04-29' ORDER BY ps_suppkey ASC, l_shipmode ASC, p_name DESC
SELECT l_receiptdate, s_name, ps_comment FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey WHERE l_tax >= 0.05 AND l_comment >= 'ts cajole ironic courts. bol' AND l_linenumber >= 5 AND s_address <> 'Cs93kCGRA6HlNVZjgrU,5Fi 1F3 vx'
select c_nationkey, o_custkey, n_name, c_mktsegment from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name >= 'Customer#000086870' AND o_orderdate >= '1993-05-19' AND c_comment = 'are blithely until the slyly even deposits. slyly express requests against the furiously even pinto beans slee' order by c_nationkey ASC, c_mktsegment DESC, o_custkey ASC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#11'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 2 and l_quantity <= 2 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#52'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 14 and l_quantity <= 14 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#23'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 30 and l_quantity <= 30 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%dark%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'ROMANIA' and n2.n_name = 'VIETNAM')     or (n1.n_name = 'VIETNAM' and n2.n_name = 'ROMANIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select l_receiptdate, o_totalprice from orders, lineitem where o_orderpriority <= '3-MEDIUM' AND o_totalprice = 306396.41 AND o_custkey > 71746 AND l_tax > 0.03 order by o_totalprice DESC, l_receiptdate ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('10', '20', '13', '19', '12', '23', '11')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('10', '20', '13', '19', '12', '23', '11')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select c_nationkey, c_name, n_regionkey, o_custkey from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where o_orderdate = '1995-07-01' AND r_name < 'MIDDLE EAST' AND o_comment = 'ggle. carefully ironic ideas' order by c_nationkey ASC, n_regionkey DESC, o_custkey ASC
select o_orderpriority, l_returnflag, ps_availqty from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where l_returnflag > 'N' AND l_partkey = 141608 AND l_shipinstruct >= 'COLLECT COD' AND o_orderdate = '1996-04-04'
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'IRAN' and n2.n_name = 'ALGERIA')     or (n1.n_name = 'ALGERIA' and n2.n_name = 'IRAN')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select s_name, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_comment = 'ake furiously blithe requests. permanently ruthless accounts cajole along the boldly regular attainments. quickly regular' AND ps_supplycost >= 983.45 AND ps_partkey <= 173618 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
select ps_availqty, l_returnflag, l_shipinstruct from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1997-03-17' AND l_partkey = 117322 AND o_orderpriority >= '5-LOW' AND l_returnflag = 'A'
SELECT s_nationkey, n_name, r_name, ps_availqty FROM region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey WHERE n_comment >= 'platelets. blithely pending dependencies use fluffily across the even pinto beans. carefully silent accoun' AND n_name > 'MOZAMBIQUE' AND s_suppkey < 1933
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('14', '29', '22', '24', '32', '15', '19')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('14', '29', '22', '24', '32', '15', '19')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%wheat%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1995-06-01'  and o_orderdate < date '1995-06-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'HOUSEHOLD' AND o_orderdate = '1993-09-18' AND o_custkey < 99011 AND o_orderkey < 2232065
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 42  and p_type like '%STEEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT c_acctbal, l_commitdate, o_orderstatus, ps_suppkey FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE l_receiptdate = '1998-06-30' AND l_shipinstruct > 'TAKE BACK RETURN' AND c_phone >= '19-646-636-2249' ORDER BY o_orderstatus DESC, ps_suppkey DESC, l_commitdate DESC, c_acctbal DESC
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'A' AND p_brand > 'Brand#23' AND ps_supplycost = 807.61 AND l_linenumber = 7 order by p_mfgr DESC, l_linenumber ASC
select o_orderdate, o_comment from customer JOIN orders ON o_custkey = c_custkey where c_custkey = 33278 AND o_orderdate = '1993-09-18' AND o_custkey < 32722 AND c_comment < 'ggle carefully after the furiously regular theodolites; slyly quick requests are. carefull'
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#22'  and p_type not like 'LARGE BURNISHED%'  and p_size in (21, 16, 4, 5, 25, 12, 45, 37)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('14', '21', '20', '11', '32', '27', '16')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('14', '21', '20', '11', '32', '27', '16')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT s_comment, l_suppkey, n_regionkey, ps_availqty FROM nation JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE ps_partkey < 59366 AND s_phone <= '32-767-307-2688' AND s_name > 'Supplier#000009068' AND n_nationkey <= 21 ORDER BY ps_availqty ASC, n_regionkey ASC, l_suppkey DESC
select l_commitdate, ps_availqty from lineitem, partsupp where l_linestatus = 'F' AND l_orderkey < 5862276 AND l_tax < 0.07 AND l_extendedprice = 41364.0
select ps_comment, s_name, p_mfgr, r_comment, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where r_name < 'AMERICA' AND ps_availqty = 5354 AND n_comment = 'requests against the platelets use never according to the quickly regular pint'
select  o_year,  sum(case   when nation = 'FRANCE' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL BRUSHED TIN'  ) as all_nations group by  o_year order by  o_year ;
select p_name, l_commitdate, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where p_container = 'WRAP CASE' AND p_brand > 'Brand#23' AND l_commitdate = '1998-10-10' AND l_orderkey < 2618950 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by ps_partkey DESC, p_name ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('33', '22', '29', '25', '32', '12', '31')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('33', '22', '29', '25', '32', '12', '31')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select p_mfgr, ps_availqty, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 9188 AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 59800 group by p_mfgr, ps_availqty having min(p_container) = 'MED PKG'
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1994-01-01'  and l_shipdate < date '1994-01-01' + interval '1' month ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 14  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  o_year,  sum(case   when nation = 'ARGENTINA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'ECONOMY ANODIZED TIN'  ) as all_nations group by  o_year order by  o_year ;
