select s_nationkey, l_returnflag, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipdate = '1993-09-05' AND l_quantity = 11.0 AND s_suppkey = 1933 order by ps_partkey DESC, s_nationkey ASC
