select  o_year,  sum(case   when nation = 'CHINA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'LARGE PLATED STEEL'  ) as all_nations group by  o_year order by  o_year ;
SELECT c_phone, o_custkey FROM customer JOIN orders ON o_custkey = c_custkey WHERE o_comment <> 'regular dolphins. regular, regular foxes are a' AND c_acctbal >= 8771.87 AND o_orderstatus < 'O' AND c_name = 'Customer#000067979'
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'grey%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1997-01-01'      and l_shipdate < date '1997-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'KENYA' order by  s_name ;
select l_extendedprice, l_commitdate from lineitem, partsupp where l_orderkey = 2387522 AND ps_availqty < 7752 AND l_tax < 0.07 AND l_linestatus = 'O'
SELECT c_custkey, o_comment, n_nationkey, MIN(c_comment) FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE c_phone > '34-687-632-7137' AND c_name = 'Customer#000127587' GROUP BY c_custkey, o_comment, n_nationkey HAVING MIN(c_comment) <= 'beans hinder blithely sometimes final platele' ORDER BY MIN(c_comment) ASC
SELECT s_acctbal, p_size, ps_comment, n_regionkey, MIN(n_comment) FROM nation JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey WHERE ps_availqty = 6331 AND p_retailprice <= 1784.79 GROUP BY s_acctbal, p_size, ps_comment, n_regionkey HAVING MIN(n_comment) = 'ic deposits are blithely about the carefully regular pa' ORDER BY n_regionkey ASC, p_size ASC
SELECT c_mktsegment, o_orderdate, n_comment, s_comment FROM supplier JOIN nation ON n_nationkey = s_nationkey JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE c_comment >= 'ar accounts against the carefully even deposits wake carefully' AND c_name >= 'Customer#000074814' AND n_comment = 'haggle. carefully final deposits detect slyly agai' AND c_address = 'GXiKB59Toehqm,B'
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#11'  and p_type not like 'SMALL BURNISHED%'  and p_size in (21, 10, 30, 26, 27, 47, 8, 38)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select ps_suppkey, r_comment, r_regionkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where ps_partkey > 196386 AND r_regionkey < 0 group by ps_suppkey, r_regionkey, n_regionkey, r_comment order by ps_suppkey DESC, r_regionkey DESC
select p_brand, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'N' AND p_mfgr > 'Manufacturer#5' AND l_linenumber = 6 AND ps_supplycost = 88.04 order by ps_comment DESC, l_linenumber ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#23'  and p_type not like 'PROMO ANODIZED%'  and p_size in (31, 48, 14, 47, 13, 44, 25, 39)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'BUILDING'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-16'  and l_shipdate > date '1995-03-16' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
SELECT l_comment, o_orderstatus FROM orders JOIN lineitem ON l_orderkey = o_orderkey WHERE l_linestatus = 'F' AND l_receiptdate < '1998-01-15' AND o_orderdate = '1997-07-23' AND o_orderstatus <> 'F'
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('30', '12', '13', '22', '25', '23', '26')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('30', '12', '13', '22', '25', '23', '26')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
