SELECT ps_suppkey, l_shipdate FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_partkey = 103066 AND ps_supplycost >= 757.42 AND l_tax > 0.02 AND l_returnflag <> 'R' ORDER BY l_shipdate DESC, ps_suppkey ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('23', '32', '33', '12', '25', '17', '18')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('23', '32', '33', '12', '25', '17', '18')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
