select c_nationkey, o_orderstatus, n_comment from orders, customer, nation where o_totalprice < 36447.99 AND c_acctbal = 7048.34 AND c_name = 'Customer#000145659' AND c_mktsegment > 'AUTOMOBILE' AND o_shippriority < 0
SELECT c_acctbal, o_orderpriority, MAX(c_name) FROM customer, orders WHERE c_custkey = 43536 AND o_orderpriority = '3-MEDIUM' AND c_nationkey >= 15 GROUP BY c_acctbal, o_orderpriority HAVING MAX(c_name) = 'Customer#000067979'
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'EGYPT' and n2.n_name = 'ETHIOPIA')     or (n1.n_name = 'ETHIOPIA' and n2.n_name = 'EGYPT')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select ps_comment, s_phone, l_discount, min(s_name), sum(l_orderkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '32-950-749-3092' AND s_name >= 'Supplier#000001926' AND l_partkey > 167548 group by ps_comment, l_discount, s_phone having min(s_name) <= 'Supplier#000006418' order by sum(l_orderkey) DESC, min(s_name) ASC
SELECT o_orderstatus, c_acctbal FROM orders, customer WHERE c_acctbal = 1438.98 AND o_custkey <> 75991 AND c_comment <= 'e carefully regular instructions. furiously even packages engage quickly against' AND c_nationkey = 15 ORDER BY o_orderstatus ASC, c_acctbal ASC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'RUSSIA' and n2.n_name = 'UNITED KINGDOM')     or (n1.n_name = 'UNITED KINGDOM' and n2.n_name = 'RUSSIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('FOB', 'AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1994-01-01'  and l_receiptdate < date '1994-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  o_year,  sum(case   when nation = 'RUSSIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'STANDARD POLISHED STEEL'  ) as all_nations group by  o_year order by  o_year ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#11'  and p_type not like 'MEDIUM PLATED%'  and p_size in (19, 36, 24, 17, 15, 13, 2, 18)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%blue%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'INDIA' and n2.n_name = 'VIETNAM')     or (n1.n_name = 'VIETNAM' and n2.n_name = 'INDIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select o_orderstatus, l_extendedprice from lineitem, orders where l_suppkey >= 5085 AND l_linestatus = 'F' AND o_totalprice = 37462.59 AND o_totalprice = 167218.71
select ps_supplycost, s_suppkey, s_address, s_name, count(ps_partkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 8448 group by s_address, s_suppkey, s_name, ps_supplycost order by s_suppkey DESC, ps_supplycost DESC
select n_regionkey, s_comment, r_regionkey, ps_suppkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 12 AND ps_suppkey >= 8448 group by ps_suppkey, r_regionkey, s_comment, n_regionkey order by ps_suppkey DESC, r_regionkey DESC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'IRAN' and n2.n_name = 'JAPAN')     or (n1.n_name = 'JAPAN' and n2.n_name = 'IRAN')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1997-12-01'  and l_shipdate < date '1997-12-01' + interval '1' month ;
SELECT c_name, o_custkey FROM customer JOIN orders ON o_custkey = c_custkey WHERE o_orderstatus <= 'F' AND o_custkey <= 11008 AND o_orderdate > '1995-07-01' AND c_address <= 'JaLWr3HdBDxkCkb3VVxig9uP9jmboNlT9cG7DBR'
SELECT ps_partkey, p_mfgr, l_shipmode FROM part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_shipinstruct <= 'TAKE BACK RETURN' AND l_orderkey >= 4504998 AND p_type = 'MEDIUM POLISHED BRASS' ORDER BY p_mfgr DESC, l_shipmode DESC, ps_partkey ASC
select o_custkey from orders where o_orderdate = '1993-08-21' AND o_orderstatus = 'O' AND o_shippriority >= 0 AND o_orderkey >= 2814018 order by o_custkey ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 49  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#54'  and p_type not like 'PROMO BRUSHED%'  and p_size in (32, 23, 22, 50, 40, 19, 24, 14)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select ps_availqty, ps_comment, r_comment, r_name, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where r_name < 'AMERICA' AND ps_availqty = 8560 AND n_comment = 'al foxes promise slyly according to the regular accounts. bold requests alon'
SELECT ps_partkey, s_nationkey FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey WHERE s_nationkey > 14 AND ps_availqty = 3837 AND ps_comment < 'luffily. furiously special pinto beans nag furiously? carefully pending requests sleep carefully. ironic accounts h' AND s_suppkey > 1154 ORDER BY s_nationkey ASC, ps_partkey DESC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('15', '31', '20', '19', '29', '27', '26')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('15', '31', '20', '19', '29', '27', '26')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#13'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 6 and l_quantity <= 6 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#43'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 11 and l_quantity <= 11 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#55'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 27 and l_quantity <= 27 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('REG AIR', 'MAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT o_clerk, n_regionkey, c_address FROM orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey WHERE c_custkey > 54178 AND n_comment >= 'ven packages wake quickly. regu' AND c_nationkey >= 4 AND n_name >= 'INDIA' ORDER BY o_clerk ASC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('REG AIR', 'TRUCK')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT l_linenumber, ps_availqty, c_phone, s_comment, n_comment, MAX(s_comment) FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN customer ON c_nationkey = n_nationkey WHERE s_phone < '25-585-189-5975' AND l_extendedprice = 74957.22 GROUP BY l_linenumber, ps_availqty, c_phone, s_comment, n_comment
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'wheat%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1994-01-01'      and l_shipdate < date '1994-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'IRAQ' order by  s_name ;
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'AUTOMOBILE' AND o_orderdate = '1993-08-25' AND o_custkey < 77639 AND o_orderkey < 2738496
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'BRAZIL' and n2.n_name = 'IRAN')     or (n1.n_name = 'IRAN' and n2.n_name = 'BRAZIL')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('13', '14', '27', '26', '30', '31', '17')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('13', '14', '27', '26', '30', '31', '17')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT c_nationkey, n_comment, r_comment, o_orderpriority FROM orders, customer, nation, region WHERE o_comment = 'y even decoys serve fluffily. pending, pen' AND o_orderdate > '1995-09-26' AND c_acctbal <= 7232.97 AND c_name < 'Customer#000060617' AND n_name <= 'INDONESIA'
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#41'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 5 and l_quantity <= 5 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#32'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 20 and l_quantity <= 20 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#22'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 23 and l_quantity <= 23 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'AUTOMOBILE' AND o_orderdate = '1993-09-18' AND o_custkey < 9136 AND o_orderkey < 2232065
select p_comment, ps_comment, l_shipmode from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 88960 AND ps_comment = 'lent accounts detect quickly accounts. regularly regular foxes haggle furiously. foxes use alongside of the special, pending pinto beans. deposits sleep. furiously unu' AND p_retailprice = 978.04 AND l_shipinstruct <= 'DELIVER IN PERSON'
select s_comment, l_discount, l_shipmode, max(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_suppkey = 8684 AND s_name < 'Supplier#000001926' AND l_partkey > 167548 group by s_comment, l_discount, l_shipmode having sum(ps_partkey) <= 198332 order by sum(ps_partkey) DESC, max(s_name) ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#41'  and p_type not like 'PROMO ANODIZED%'  and p_size in (34, 10, 44, 45, 19, 26, 18, 47)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT n_nationkey, o_shippriority, s_address, c_nationkey FROM orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN supplier ON s_nationkey = n_nationkey WHERE c_mktsegment <= 'AUTOMOBILE' AND s_name = 'Supplier#000006015' AND n_nationkey < 6 AND n_comment = 'ss excuses cajole slyly across the packages. deposits print aroun' ORDER BY s_address ASC, c_nationkey DESC, o_shippriority DESC, n_nationkey ASC
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%bisque%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
