select s_nationkey, ps_availqty from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_supplycost >= 520.94 AND s_comment < 'egular requests. slyly special requests sleep furiously carefully bold dep' AND ps_partkey <= 143679 AND ps_supplycost < 835.16 AND s_nationkey > 6 AND s_acctbal <= 5433.53
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('19', '15', '27', '34', '33', '21', '26')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('19', '15', '27', '34', '33', '21', '26')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
