SELECT s_name, ps_suppkey, l_returnflag FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE s_acctbal <= 6151.79 AND l_suppkey > 4245 AND ps_partkey = 146694 ORDER BY l_returnflag DESC, s_name DESC, ps_suppkey DESC
select p_retailprice, l_shipinstruct, ps_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_shipmode = 'AIR' AND ps_comment = 've carefully. quickly final packages about the caref' AND p_comment = 'equests wake ab' AND l_partkey <= 191428
