select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'F' AND p_type = 'STANDARD BRUSHED STEEL' AND l_commitdate = '1993-05-13' AND l_orderkey < 4758179 AND ps_comment > 'detect blithely even theodolites. blithely permanent accounts cajole carefully ironic deposits. ironic, careful instructions are i' order by ps_partkey DESC, p_name ASC
