select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#51'  and p_type not like 'PROMO BRUSHED%'  and p_size in (38, 48, 15, 50, 43, 30, 47, 26)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
SELECT l_receiptdate, o_totalprice FROM orders, lineitem WHERE o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 168844.46 AND o_custkey > 71746 AND l_tax > 0.02 ORDER BY o_totalprice DESC, l_receiptdate ASC
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%slate%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
