select l_shipinstruct, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 49449 AND l_shipmode = 'RAIL' AND p_retailprice = 1920.87 AND ps_comment <= '. ironic requests above the always ironic theodolites cajole blithely along the platelets. slyly even sheave'
SELECT ps_availqty, n_nationkey, s_phone FROM partsupp, supplier, nation WHERE ps_supplycost <= 45.64 AND s_address = 'C7CwN6SZ0ikFPW' AND ps_comment <> 'uffily express instructions. carefully special theodolites are against the final packages. furiously ironic pains sleep quickly about' AND s_nationkey > 11
select o_custkey from orders where o_orderdate <= '1994-08-04' AND o_orderstatus <= 'P' AND o_shippriority >= 0 AND o_orderkey = 702946 order by o_custkey ASC
select l_shipinstruct, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 144089 AND ps_comment = 'final packages affix regularly pending pinto beans. fluffily regular excuses doubt carefully. ironic accounts are slyly. express, bold dolphins nag-- even, bold requests hang' AND l_shipmode = 'RAIL' AND p_retailprice <= 1275.35
select  s_name,  count(*) as numwait from  supplier,  lineitem l1,  orders,  nation where  s_suppkey = l1.l_suppkey  and o_orderkey = l1.l_orderkey  and o_orderstatus = 'F'  and l1.l_receiptdate > l1.l_commitdate  and exists (   select    *   from    lineitem l2   where    l2.l_orderkey = l1.l_orderkey    and l2.l_suppkey <> l1.l_suppkey  )  and not exists (   select    *   from    lineitem l3   where    l3.l_orderkey = l1.l_orderkey    and l3.l_suppkey <> l1.l_suppkey    and l3.l_receiptdate > l3.l_commitdate  )  and s_nationkey = n_nationkey  and n_name = 'ARGENTINA' group by  s_name order by  numwait desc,  s_name limit 100;
select l_receiptdate, l_tax from orders, lineitem where o_orderpriority <= '1-URGENT' AND o_totalprice = 206608.97 AND o_custkey > 140612 AND o_totalprice > 6631.56 order by l_receiptdate DESC, l_tax ASC
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1996-05-01'  and o_orderdate < date '1996-05-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%metallic%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'DELIVER IN PERSON' AND s_name = 'Supplier#000002068' AND s_suppkey = 1933 order by ps_partkey DESC, s_name ASC
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'snow%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1996-01-01'      and l_shipdate < date '1996-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'JAPAN' order by  s_name ;
select l_comment, l_shipmode, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_orderkey = 172162 AND s_suppkey = 7041 AND s_suppkey = 1933 order by ps_partkey DESC, l_shipmode ASC
select ps_suppkey, ps_availqty, n_nationkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where ps_supplycost > 504.43 AND s_phone >= '31-367-113-9243' group by ps_suppkey, ps_availqty, n_nationkey, n_regionkey order by ps_suppkey DESC, ps_availqty DESC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#13'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 6 and l_quantity <= 6 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#23'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 13 and l_quantity <= 13 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#45'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 26 and l_quantity <= 26 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#52'  and p_type not like 'PROMO POLISHED%'  and p_size in (26, 46, 28, 50, 36, 9, 44, 7)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#24'  and p_container = 'MED PACK'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT l_orderkey, o_orderpriority, MAX(l_returnflag) FROM orders JOIN lineitem ON l_orderkey = o_orderkey WHERE o_shippriority < 0 AND l_linestatus > 'F' AND o_orderpriority <= '1-URGENT' GROUP BY l_orderkey, o_orderpriority HAVING MAX(l_returnflag) < 'N' ORDER BY MAX(l_returnflag) DESC
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1996-07-01'  and l_shipdate < date '1996-07-01' + interval '1' month ;
SELECT n_name, l_shipdate, c_name, o_orderpriority FROM lineitem JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey WHERE n_regionkey <= 0 AND l_shipdate > '1996-03-16' AND c_nationkey <= 14 AND l_extendedprice <> 12604.32
select l_commitdate, ps_availqty from lineitem, partsupp where l_tax = 0.07 AND l_extendedprice < 26883.18 AND l_linestatus < 'F' AND l_orderkey = 4582434
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1993-08-01'  and l_shipdate < date '1993-08-01' + interval '1' month ;
SELECT l_shipinstruct, ps_supplycost FROM partsupp JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_quantity < 16.0 AND l_shipdate = '1995-10-31' AND l_orderkey <= 5092134 AND l_returnflag = 'R' AND l_partkey > 157038
select  o_year,  sum(case   when nation = 'JORDAN' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO BURNISHED TIN'  ) as all_nations group by  o_year order by  o_year ;
select l_shipinstruct, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 120307 AND ps_comment = 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND l_shipmode = 'SHIP' AND p_retailprice <= 1831.73
SELECT n_regionkey, r_name, o_orderpriority, c_name FROM orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey WHERE n_nationkey > 15 AND c_custkey < 74223 AND c_mktsegment = 'MACHINERY' ORDER BY o_orderpriority ASC, c_name DESC
select  c_name,  c_custkey,  o_orderkey,  o_orderdate,  o_totalprice,  sum(l_quantity) from  customer,  orders,  lineitem where  o_orderkey in (   select    l_orderkey   from    lineitem   group by    l_orderkey having     sum(l_quantity) > 312  )  and c_custkey = o_custkey  and o_orderkey = l_orderkey group by  c_name,  c_custkey,  o_orderkey,  o_orderdate,  o_totalprice order by  o_totalprice desc,  o_orderdate limit 100;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#12'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 1 and l_quantity <= 1 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 18 and l_quantity <= 18 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#22'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 28 and l_quantity <= 28 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select ps_partkey, ps_comment, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty > 2481 AND p_mfgr = 'Manufacturer#1' AND ps_partkey <= 180166 group by ps_comment, ps_partkey having min(p_container) = 'JUMBO CASE'
SELECT l_shipdate, o_shippriority FROM lineitem, orders WHERE o_custkey < 30488 AND l_partkey = 147429 AND l_linestatus <= 'F' AND l_receiptdate <> '1997-02-10' AND l_shipmode > 'RAIL' AND o_totalprice <= 168844.46 AND l_shipinstruct <= 'DELIVER IN PERSON' ORDER BY l_shipdate ASC
select l_receiptdate, l_tax from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 86212.42 AND o_totalprice > 204986.86 AND o_custkey > 9136 order by l_tax DESC, l_receiptdate ASC
select  o_year,  sum(case   when nation = 'JAPAN' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO BRUSHED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#31'  and p_type not like 'LARGE ANODIZED%'  and p_size in (7, 6, 35, 4, 42, 23, 49, 32)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#32'  and p_container = 'LG PACK'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'MOZAMBIQUE' and n2.n_name = 'PERU')     or (n1.n_name = 'PERU' and n2.n_name = 'MOZAMBIQUE')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select ps_comment, s_phone from partsupp JOIN supplier ON s_suppkey = ps_suppkey where s_nationkey >= 12 AND ps_partkey < 65143 AND s_name <= 'Supplier#000003068' AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
select l_receiptdate, o_orderkey from orders, lineitem where o_shippriority <= 0 AND o_totalprice > 168844.46 AND o_comment = 'epitaphs. special accounts despite the pending accounts nag slyly among the' AND l_tax > 0.02 order by l_receiptdate DESC, o_orderkey ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('29', '10', '24', '25', '19', '34', '20')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('29', '10', '24', '25', '19', '34', '20')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'salmon%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1996-01-01'      and l_shipdate < date '1996-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'MOROCCO' order by  s_name ;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1995-03-01'  and l_shipdate < date '1995-03-01' + interval '1' month ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('22', '19', '20', '25', '28', '17', '27')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('22', '19', '20', '25', '28', '17', '27')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 3938 AND s_comment < 'ffix slyly after the slyly special accounts. regular ideas among the fu' AND ps_partkey <= 5023 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 248.17
SELECT s_comment, ps_supplycost, n_comment, r_comment, MAX(ps_suppkey) FROM region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey WHERE n_name = 'IRAQ' AND s_comment > 'final, busy instructions. carefully regular requests about the carefully express packages' GROUP BY s_comment, ps_supplycost, n_comment, r_comment HAVING MAX(ps_suppkey) <> 2074
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'BUILDING'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-04'  and l_shipdate > date '1995-03-04' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%green%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 18  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%floral%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
SELECT ps_partkey FROM partsupp WHERE ps_supplycost < 374.34 AND ps_availqty > 9354 AND ps_comment >= 'uests along the regular platelets nag furiously against the slyly silent ideas-- quickly pending foxes cajole furiously slyly even i' AND ps_suppkey > 249 AND ps_partkey <> 155621
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%blanched%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'TAKE BACK RETURN' AND s_name = 'Supplier#000009565' AND s_suppkey = 3861 order by ps_partkey DESC, s_name ASC
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#33'  and p_container = 'SM DRUM'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#21'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 4 and l_quantity <= 4 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#53'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 18 and l_quantity <= 18 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#41'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 30 and l_quantity <= 30 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  n_name,  sum(l_extendedprice * (1 - l_discount)) as revenue from  customer,  orders,  lineitem,  supplier,  nation,  region where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and l_suppkey = s_suppkey  and c_nationkey = s_nationkey  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and o_orderdate >= date '1996-01-01'  and o_orderdate < date '1996-01-01' + interval '1' year group by  n_name order by  revenue desc ;
SELECT n_name, ps_suppkey, s_acctbal, COUNT(n_regionkey), AVG(s_suppkey) FROM partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey WHERE ps_comment <> 'foxes. bold, special deposits doze carefully alongside of the requests. boldly regular accounts haggle. special the' AND s_address > 'Rz1JMCsGrIGvAJ,FkwTy ydL KwH' AND s_comment > 'w dolphins. carefully final instructions use silently bold pinto beans. fur' AND s_acctbal > 4549.09 GROUP BY n_name, ps_suppkey, s_acctbal ORDER BY s_acctbal ASC
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%gainsboro%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('24', '27', '12', '33', '21', '25', '32')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('24', '27', '12', '33', '21', '25', '32')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT l_comment FROM lineitem WHERE l_discount >= 0.09 AND l_tax <= 0.07 AND l_orderkey > 4582434 AND l_comment <= 'regular instructions. ironic,' ORDER BY l_comment DESC
SELECT ps_comment, l_shipmode, MIN(ps_availqty) FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE ps_suppkey > 6825 AND ps_supplycost = 983.45 AND l_linestatus >= 'O' GROUP BY ps_comment, l_shipmode ORDER BY MIN(ps_availqty) DESC
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%maroon%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('SHIP', 'RAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('32', '33', '17', '12', '14', '30', '21')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('32', '33', '17', '12', '14', '30', '21')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#15'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 2 and l_quantity <= 2 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#23'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 16 and l_quantity <= 16 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#51'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 29 and l_quantity <= 29 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1994-09-01'  and o_orderdate < date '1994-09-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
SELECT s_suppkey, n_comment, ps_suppkey FROM partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey WHERE s_nationkey > 15 AND ps_suppkey >= 6579 AND n_comment <> 'eans boost carefully special requests. accounts are. carefull' AND ps_supplycost = 943.73 ORDER BY ps_suppkey DESC, s_suppkey DESC
SELECT ps_suppkey, s_suppkey, MAX(s_suppkey) FROM partsupp, supplier WHERE s_comment <= 'carefully final packages haggle bold deposits. carefully silent war' AND ps_comment = 'uses print after the even packages. furiously regular instructions above the deposits sleep after the blithely ruthless deposits. ca' AND s_phone <> '23-696-420-8788' GROUP BY ps_suppkey, s_suppkey HAVING MAX(s_suppkey) >= 5490 ORDER BY MAX(s_suppkey) DESC
SELECT l_partkey FROM lineitem WHERE l_shipdate <> '1994-07-10' AND l_quantity <= 48.0 AND l_linenumber >= 2 AND l_shipmode <> 'FOB' AND l_linestatus < 'F' AND l_receiptdate <= '1998-06-30'
select s_comment, r_regionkey, ps_suppkey, n_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where s_nationkey > 1 AND ps_suppkey >= 1021 group by ps_suppkey, s_comment, r_regionkey, n_regionkey order by ps_suppkey DESC, r_regionkey DESC
select s_comment, s_phone, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_name = 'Supplier#000005069' AND l_partkey < 15136 AND ps_partkey > 120117 group by s_comment, s_phone, l_shipmode having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
SELECT l_quantity, ps_supplycost FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_quantity >= 11.0 AND l_linenumber < 5 AND ps_availqty <= 9419 AND l_shipdate = '1993-03-28' ORDER BY l_quantity DESC
select p_retailprice, ps_suppkey, max(p_type) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 9188 AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 180166 group by ps_suppkey, p_retailprice having max(p_type) = 'PROMO ANODIZED STEEL'
select o_clerk from orders where o_orderdate >= '1993-08-21' AND o_orderdate = '1995-09-02' AND o_comment >= 'ccounts haggle quickly final excuses. fluffily e' AND o_orderkey = 1472992 order by o_clerk ASC
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '110' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#22'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 5 and l_quantity <= 5 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#44'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 19 and l_quantity <= 19 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 27 and l_quantity <= 27 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
SELECT l_tax, ps_partkey, p_name FROM part, partsupp, lineitem WHERE l_returnflag = 'R' AND ps_partkey = 71581 AND l_discount > 0.1 AND l_linenumber < 4 AND p_mfgr > 'Manufacturer#5' ORDER BY ps_partkey ASC, p_name ASC, l_tax DESC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('MAIL', 'REG AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
SELECT s_name, l_comment, o_orderpriority, c_acctbal, ps_supplycost FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey JOIN customer ON c_custkey = o_custkey WHERE s_nationkey <> 5 AND l_linestatus < 'F' AND l_returnflag <= 'A' ORDER BY l_comment DESC, ps_supplycost ASC
select l_shipinstruct, l_suppkey, p_name from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 91990 AND ps_comment = 'ly unusual foxes nod according to the pending packages. blithely express requests wake above the regular, even deposits. special accounts against the quickly special asymptotes hag' AND l_extendedprice = 58974.4 AND p_retailprice <= 1831.73
SELECT c_mktsegment, o_custkey, n_regionkey FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey WHERE o_clerk = 'Clerk#000000101' AND c_mktsegment >= 'AUTOMOBILE' AND c_custkey >= 71324 AND c_nationkey > 1
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#45'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 3 and l_quantity <= 3 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#14'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 19 and l_quantity <= 19 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#44'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 29 and l_quantity <= 29 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#51'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 8 and l_quantity <= 8 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#24'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 13 and l_quantity <= 13 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#55'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 27 and l_quantity <= 27 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select s_comment, ps_partkey, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '17-292-821-2297' AND s_name < 'Supplier#000000986' AND l_partkey > 108967 group by s_comment, ps_partkey, l_shipmode having min(s_name) <= 'Supplier#000008309' order by sum(ps_partkey) DESC, min(s_name) ASC
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('FOB', 'TRUCK')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('SHIP', 'RAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'FURNITURE' AND o_orderdate = '1993-09-18' AND o_custkey < 99011 AND o_orderkey < 401350
select p_mfgr, ps_availqty, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 8735 AND p_mfgr = 'Manufacturer#2' AND ps_partkey <= 180166 group by p_mfgr, ps_availqty having min(p_container) = 'LG CAN'
SELECT c_name, o_orderstatus FROM orders, customer WHERE o_shippriority < 0 AND c_nationkey > 16 AND o_custkey < 99901 AND c_acctbal > 3994.58 AND c_custkey > 139575
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('31', '13', '33', '27', '12', '17', '14')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('31', '13', '33', '27', '12', '17', '14')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#53'  and p_type not like 'STANDARD PLATED%'  and p_size in (34, 49, 40, 22, 13, 30, 50, 10)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#45'  and p_type not like 'LARGE POLISHED%'  and p_size in (44, 16, 26, 8, 10, 40, 7, 17)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select o_shippriority, o_totalprice from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 168844.46 AND o_custkey = 20512 AND l_tax > 0.02 order by o_totalprice DESC, o_shippriority ASC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'ROMANIA' and n2.n_name = 'INDIA')     or (n1.n_name = 'INDIA' and n2.n_name = 'ROMANIA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
SELECT c_comment, o_orderstatus, n_name, l_suppkey FROM nation JOIN customer ON c_nationkey = n_nationkey JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE c_nationkey > 22 AND c_comment >= 'are furiously furiously pending dolphins. furiously final theodolites haggle. slyly regula' AND o_custkey >= 17155 ORDER BY n_name ASC
