SELECT l_extendedprice, ps_comment FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey WHERE ps_availqty <> 8724 AND ps_suppkey = 6519 AND ps_comment >= 'uffily express instructions. carefully special theodolites are against the final packages. furiously ironic pains sleep quickly about' AND ps_supplycost <> 116.26 ORDER BY ps_comment ASC
select o_custkey from orders where o_orderdate <= '1997-01-27' AND o_orderstatus <= 'O' AND o_shippriority >= 0 AND o_orderkey = 1204101 order by o_custkey ASC
SELECT l_returnflag, ps_availqty FROM lineitem, partsupp WHERE l_shipmode = 'RAIL' AND l_comment < 'nusual accounts' AND l_commitdate = '1995-02-25' AND l_partkey <= 104045
select ps_availqty, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1993-04-01' AND l_partkey = 141608 AND l_returnflag >= 'N' AND l_shipinstruct = 'NONE'
SELECT n_comment, ps_comment, s_phone FROM nation JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey WHERE ps_supplycost > 943.73 AND ps_availqty >= 5354 AND n_nationkey = 9 ORDER BY n_comment DESC, ps_comment ASC, s_phone DESC
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'indian%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1994-01-01'      and l_shipdate < date '1994-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'EGYPT' order by  s_name ;
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'SAUDI ARABIA' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'SAUDI ARABIA'   ) order by  value desc ;
SELECT ps_partkey, o_comment, l_shipmode, MAX(o_shippriority) FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE l_quantity >= 35.0 AND ps_availqty < 7758 AND ps_suppkey <> 5063 AND o_orderkey = 61024 GROUP BY ps_partkey, o_comment, l_shipmode ORDER BY ps_partkey ASC, o_comment ASC
select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'O' AND p_type = 'ECONOMY BURNISHED TIN' AND l_commitdate = '1993-10-02' AND l_orderkey < 2618950 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by ps_partkey DESC, p_name ASC
SELECT l_commitdate, ps_suppkey, s_phone, AVG(ps_supplycost) FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey WHERE s_address >= 'H5tDfi,XJ8BuciyUcOao1WXbXOWIGBR' AND ps_availqty = 7950 GROUP BY l_commitdate, ps_suppkey, s_phone HAVING AVG(ps_supplycost) < 160.7 ORDER BY ps_suppkey DESC, l_commitdate ASC, s_phone ASC
select s_comment, ps_partkey, l_shipmode, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_phone = '24-810-371-6779' AND s_name < 'Supplier#000001275' AND l_partkey > 167548 group by s_comment, ps_partkey, l_shipmode having min(s_name) <= 'Supplier#000004985' order by sum(ps_partkey) DESC, min(s_name) ASC
SELECT o_shippriority FROM orders WHERE o_clerk > 'Clerk#000000950' AND o_shippriority <> 0 AND o_custkey >= 131045 AND o_orderpriority >= '4-NOT SPECIFIED' AND o_orderkey > 374980
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'HOUSEHOLD'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-04'  and l_shipdate > date '1995-03-04' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select s_comment, s_nationkey from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 1207 AND s_acctbal < 5433.53 AND ps_supplycost <= 57.43 AND ps_partkey < 5804 AND s_nationkey > 20 AND ps_supplycost <= 91.11
select p_mfgr, ps_availqty, min(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 1178 AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 198332 group by p_mfgr, ps_availqty having min(p_container) = 'LG PKG'
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'IRAN' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'IRAN'   ) order by  value desc ;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'BUILDING'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-19'  and l_shipdate > date '1995-03-19' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '113' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#21'  and p_type not like 'STANDARD BRUSHED%'  and p_size in (5, 40, 22, 8, 29, 9, 36, 1)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select c_address, o_custkey, r_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where n_name = 'UNITED KINGDOM' AND o_orderdate < '1995-01-28' AND o_comment = 'ggle. carefully ironic ideas' order by r_regionkey ASC, r_name DESC, o_custkey ASC
SELECT ps_comment, s_name, p_mfgr, r_comment, n_name FROM region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey WHERE r_name < 'AMERICA' AND ps_availqty = 8560 AND n_comment = 'al foxes promise slyly according to the regular accounts. bold requests alon'
select n_name, o_orderstatus, n_comment from orders, customer, nation where o_orderdate < '1993-09-13' AND c_acctbal = 1481.44 AND o_shippriority = 0 AND c_mktsegment > 'BUILDING' AND o_shippriority < 0
SELECT o_comment, c_nationkey FROM customer, orders WHERE o_comment >= 'ticing requests haggle slyly blithely express tithes. blithe' AND o_totalprice < 145293.14 AND c_comment >= 'ed to are fluffily. foxes hag' AND c_phone = '13-268-469-1359'
select  o_year,  sum(case   when nation = 'FRANCE' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'LARGE ANODIZED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('AIR', 'MAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1993-01-01'  and l_receiptdate < date '1993-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  o_year,  sum(case   when nation = 'ROMANIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'ECONOMY POLISHED STEEL'  ) as all_nations group by  o_year order by  o_year ;
SELECT p_mfgr, ps_availqty, MIN(p_container) FROM part JOIN partsupp ON ps_partkey = p_partkey WHERE ps_availqty = 9188 AND p_mfgr <> 'Manufacturer#4' AND ps_partkey <= 180166 GROUP BY p_mfgr, ps_availqty HAVING MIN(p_container) = 'JUMBO CASE'
SELECT o_orderpriority, s_phone, c_name, n_comment, MAX(n_comment) FROM orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN supplier ON s_nationkey = n_nationkey WHERE c_address = 'bMJk9yfM5zrJ' AND o_comment <> 'al packages breach carefully quickly final packages. slyly' GROUP BY o_orderpriority, s_phone, c_name, n_comment HAVING MAX(n_comment) > 'platelets. blithely pending dependencies use fluffily across the even pinto beans. carefully silent accoun'
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 45  and p_type like '%BRASS'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
SELECT l_shipinstruct, o_orderstatus, ps_partkey, MIN(ps_comment) FROM orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE o_orderkey >= 5504608 AND l_shipinstruct <> 'DELIVER IN PERSON' AND l_suppkey = 8540 GROUP BY l_shipinstruct, o_orderstatus, ps_partkey HAVING MIN(ps_comment) <= 'arefully quiet instructions wake along the slyly'
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%moccasin%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1997-11-01'  and l_shipdate < date '1997-11-01' + interval '1' month ;
select  o_year,  sum(case   when nation = 'SAUDI ARABIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'LARGE PLATED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
select l_shipinstruct, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 120307 AND ps_comment = 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND l_shipmode <= 'SHIP' AND p_mfgr <= 'Manufacturer#4'
select  o_year,  sum(case   when nation = 'VIETNAM' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL BRUSHED TIN'  ) as all_nations group by  o_year order by  o_year ;
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1993-01-01'  and l_shipdate < date '1993-01-01' + interval '1' year  and l_discount between 0.04 - 0.01 and 0.04 + 0.01  and l_quantity < 24 ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('16', '20', '29', '28', '13', '19', '23')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('16', '20', '29', '28', '13', '19', '23')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT o_orderkey, l_commitdate FROM lineitem JOIN orders ON o_orderkey = l_orderkey WHERE o_orderpriority > '5-LOW' AND l_partkey <> 25 AND l_comment <= 'pinto beans. pending, spec' AND o_orderstatus <> 'P' ORDER BY o_orderkey ASC, l_commitdate DESC
select c_nationkey, o_custkey, n_regionkey, o_orderdate from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000105702' AND r_name < 'ASIA' AND o_comment = 'l orbits around the' order by c_nationkey ASC, n_regionkey DESC, o_orderdate ASC
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'AUTOMOBILE'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-12'  and l_shipdate > date '1995-03-12' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%pale%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select l_orderkey, l_linestatus, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus > 'O' AND l_linenumber = 7 AND ps_suppkey >= 6273 AND l_orderkey < 2618950 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by ps_partkey DESC, l_orderkey ASC
select o_totalprice, o_orderpriority from orders, lineitem where l_tax <= 0.07 AND o_totalprice = 168844.46 AND l_receiptdate > '1995-07-07' AND o_custkey > 125812 order by o_totalprice DESC, o_orderpriority ASC
SELECT ps_comment, l_partkey, p_container FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE ps_suppkey = 6387 AND l_shipinstruct >= 'NONE' AND l_quantity > 23.0 ORDER BY l_partkey DESC
SELECT o_orderkey, l_shipinstruct FROM orders JOIN lineitem ON l_orderkey = o_orderkey WHERE o_clerk > 'Clerk#000000345' AND l_extendedprice >= 54601.47 AND o_orderdate > '1997-02-20' AND o_comment >= 'ts. bold platelets ab'
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'SHIP')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1997-01-01'  and l_receiptdate < date '1997-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('AIR', 'REG AIR')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select p_mfgr, l_linenumber, ps_comment from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_returnflag > 'N' AND p_brand > 'Brand#12' AND ps_supplycost = 334.23 AND l_linenumber = 1 order by p_mfgr DESC, l_linenumber ASC
SELECT s_name, ps_comment, MAX(s_name), MIN(s_nationkey) FROM supplier, partsupp WHERE ps_availqty = 9934 AND s_acctbal >= 9376.37 AND s_phone = '25-418-344-7176' GROUP BY s_name, ps_comment HAVING MAX(s_name) = 'Supplier#000006725'
select  c_count,  count(*) as custdist from  (   select    c_custkey,    count(o_orderkey)   from    customer left outer join orders on     c_custkey = o_custkey     and o_comment not like '%special%requests%'   group by    c_custkey  ) as c_orders (c_custkey, c_count) group by  c_count order by  custdist desc,  c_count desc ;
select  c_custkey,  c_name,  sum(l_extendedprice * (1 - l_discount)) as revenue,  c_acctbal,  n_name,  c_address,  c_phone,  c_comment from  customer,  orders,  lineitem,  nation where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate >= date '1993-04-01'  and o_orderdate < date '1993-04-01' + interval '3' month  and l_returnflag = 'R'  and c_nationkey = n_nationkey group by  c_custkey,  c_name,  c_acctbal,  c_phone,  n_name,  c_address,  c_comment order by  revenue desc limit 20;
SELECT o_orderpriority, s_comment, n_name, l_quantity, ps_availqty FROM nation JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey JOIN orders ON o_orderkey = l_orderkey WHERE ps_supplycost <= 953.28 AND s_address = 'pIXH,lXMVPMknhTIXb4owWLtOvOmsdb' ORDER BY n_name DESC, ps_availqty DESC, s_comment ASC, l_quantity DESC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 32  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where s_comment <= 'final, busy instructions. carefully regular requests about the carefully express packages' AND l_returnflag = 'N' AND s_suppkey = 1933 order by ps_partkey DESC, s_name ASC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('14', '11', '33', '30', '29', '27', '25')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('14', '11', '33', '30', '29', '27', '25')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select l_shipinstruct, ps_comment, p_retailprice from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where p_comment = 'lyly express de' AND ps_comment = 'ts are blithely alongside of the furiously sly ideas. blithely final ideas haggle above the requests. regular accounts are carefully! slyly e' AND l_shipmode = 'SHIP' AND l_partkey <= 17221
SELECT s_phone, ps_availqty FROM partsupp, supplier WHERE s_address < 'i7o5TKSv,bYHzagKxJA4M3rtfZhRHSMvDyy8Y' AND ps_partkey > 92663 AND ps_comment <= 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND ps_suppkey > 1192 AND ps_supplycost > 628.53 AND s_phone = '25-979-553-1844' AND s_nationkey >= 10 ORDER BY ps_availqty DESC
select l_receiptdate, o_totalprice from orders, lineitem where o_orderpriority <= '4-NOT SPECIFIED' AND o_totalprice = 312536.29 AND o_custkey > 71746 AND l_tax > 0.0 order by o_totalprice DESC, l_receiptdate ASC
select  o_year,  sum(case   when nation = 'ROMANIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM ANODIZED BRASS'  ) as all_nations group by  o_year order by  o_year ;
SELECT o_orderkey FROM orders WHERE o_orderdate >= '1997-07-23' AND o_clerk = 'Clerk#000000530' AND o_orderpriority >= '3-MEDIUM' AND o_custkey < 16480 ORDER BY o_orderkey ASC
select l_comment, ps_partkey, l_shipinstruct from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where s_name = 'Supplier#000006837' AND s_name = 'Supplier#000000551' AND s_suppkey = 1933 order by l_shipinstruct DESC, ps_partkey ASC
SELECT l_shipinstruct FROM lineitem WHERE l_shipmode > 'AIR' AND l_tax > 0.08 AND l_comment = 'furiously even ideas sleep blithely.' AND l_linestatus >= 'F' ORDER BY l_shipinstruct ASC
select o_totalprice, o_custkey from customer JOIN orders ON o_custkey = c_custkey where c_comment < 'ecial dependencies. thinly quiet pinto beans sleep blith' AND o_orderdate = '1993-09-18' AND c_mktsegment < 'AUTOMOBILE' AND o_orderkey < 2232065
select  o_year,  sum(case   when nation = 'ROMANIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'EUROPE'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'SMALL BRUSHED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'CHINA' and n2.n_name = 'ROMANIA')     or (n1.n_name = 'ROMANIA' and n2.n_name = 'CHINA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('18', '10', '13', '23', '15', '33', '31')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('18', '10', '13', '23', '15', '33', '31')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('31', '19', '29', '17', '27', '20', '25')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('31', '19', '29', '17', '27', '20', '25')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select ps_partkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_supplycost = 650.88 AND s_comment < 'ic requests nag. blithely regular ideas try to wake quickly eve' AND ps_partkey < 173618 AND s_name < 'Supplier#000003848' AND s_acctbal > 6305.29 AND ps_supplycost <= 91.11
