SELECT c_phone, o_totalprice, l_partkey, ps_comment, s_suppkey FROM customer JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey WHERE l_quantity = 11.0 AND c_address >= 'nYdOZgtFmXid' AND o_orderstatus = 'O'
