select ps_availqty, o_clerk, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1995-09-02' AND l_partkey = 131411 AND l_returnflag >= 'N' AND l_shipinstruct = 'NONE'
