SELECT n_regionkey, ps_comment, s_acctbal, r_name FROM region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey WHERE s_phone >= '32-767-307-2688' AND s_name <> 'Supplier#000008309' AND ps_partkey <> 89084 AND s_nationkey = 5 ORDER BY ps_comment ASC
