SELECT l_returnflag, c_nationkey, o_orderkey FROM customer JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey WHERE c_phone = '15-128-137-7618' AND l_tax <> 0.07 AND o_custkey > 37285 ORDER BY c_nationkey DESC
SELECT ps_partkey, p_mfgr FROM partsupp, part WHERE p_comment < 's. pending accou' AND p_container <> 'MED BAG' AND ps_suppkey = 8989 AND p_brand <= 'Brand#33' AND p_size < 9 AND p_partkey <> 32078
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#32'  and p_type not like 'MEDIUM PLATED%'  and p_size in (8, 39, 9, 49, 37, 16, 43, 38)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select ps_availqty, p_mfgr, ps_partkey, p_partkey, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where s_phone < '19-247-536-8083' AND ps_availqty = 8560 AND n_comment = 'al foxes promise slyly according to the regular accounts. bold requests alon'
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '73' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
select  o_year,  sum(case   when nation = 'BRAZIL' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AMERICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'PROMO PLATED BRASS'  ) as all_nations group by  o_year order by  o_year ;
select p_partkey, ps_availqty, max(p_container) from part JOIN partsupp ON ps_partkey = p_partkey where p_partkey = 145521 AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 180166 group by p_partkey, ps_availqty having max(p_container) = 'JUMBO CASE'
SELECT o_orderstatus, l_partkey FROM lineitem, orders WHERE l_returnflag <= 'A' AND l_receiptdate <= '1998-06-30' AND l_commitdate >= '1996-01-15' AND l_shipinstruct = 'DELIVER IN PERSON' AND o_orderdate = '1992-05-23' AND o_comment = 'silent hockey players haggle'
select  n_name,  sum(l_extendedprice * (1 - l_discount)) as revenue from  customer,  orders,  lineitem,  supplier,  nation,  region where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and l_suppkey = s_suppkey  and c_nationkey = s_nationkey  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and o_orderdate >= date '1995-01-01'  and o_orderdate < date '1995-01-01' + interval '1' year group by  n_name order by  revenue desc ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 18  and p_type like '%COPPER'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('REG AIR', 'SHIP')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1996-01-01'  and l_receiptdate < date '1996-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select c_nationkey, o_orderstatus, o_custkey from orders, customer, nation where n_nationkey < 4 AND c_acctbal = 1481.44 AND c_name = 'Customer#000143733' AND c_mktsegment > 'BUILDING' AND o_shippriority < 0
select ps_comment, ps_availqty, n_nationkey from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey where s_comment >= 's quickly regular foxes. stealthily ironic p' AND n_comment = 'y above the carefully unusual theodolites. final dugouts are quickly across the furiously regular d' AND ps_availqty >= 3514 order by n_nationkey ASC
select ps_comment, s_name, p_mfgr, r_comment, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where r_name < 'AMERICA' AND ps_availqty = 1793 AND n_comment = 'refully final requests. regular, ironi'
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#44'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 3 and l_quantity <= 3 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#32'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 21 and l_quantity <= 21 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('AIR', 'RAIL')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1995-01-01'  and l_receiptdate < date '1995-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('22', '21', '29', '14', '31', '30', '33')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('22', '21', '29', '14', '31', '30', '33')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 14  and p_type like '%STEEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select n_comment, r_regionkey, p_mfgr, p_partkey, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where r_name < 'AMERICA' AND ps_availqty = 8560 AND n_comment = 'al foxes promise slyly according to the regular accounts. bold requests alon'
select ps_suppkey, n_regionkey, s_nationkey, r_regionkey, count(n_nationkey) from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey JOIN region ON r_regionkey = n_regionkey where ps_suppkey > 6231 AND s_comment >= 'ular deposits should are express foxes. furiously express excuses haggle busily. furiously' group by ps_suppkey, s_nationkey, r_regionkey, n_regionkey order by ps_suppkey DESC, r_regionkey DESC
select c_comment, o_custkey from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'MACHINERY' AND o_orderkey = 4775808 AND o_totalprice < 86212.42 AND o_orderdate < '1997-12-11'
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('34', '23', '22', '31', '12', '16', '26')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('34', '23', '22', '31', '12', '16', '26')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT s_nationkey, ps_availqty, n_comment, l_partkey, MAX(l_returnflag) FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey WHERE l_orderkey >= 5092134 AND n_comment = 'rns. blithely bold courts among the closely regular packages use furiously bold platelets?' GROUP BY s_nationkey, ps_availqty, n_comment, l_partkey HAVING MAX(l_returnflag) > 'R'
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'CANADA' and n2.n_name = 'FRANCE')     or (n1.n_name = 'FRANCE' and n2.n_name = 'CANADA')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select p_size, p_comment, min(ps_supplycost) from part JOIN partsupp ON ps_partkey = p_partkey where ps_availqty = 9188 AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 180166 group by p_comment, p_size having min(ps_supplycost) = 220.03
select ps_comment, s_name, p_mfgr, ps_partkey, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where r_name < 'AMERICA' AND ps_availqty = 8560 AND p_container = 'WRAP DRUM'
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'peach%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1997-01-01'      and l_shipdate < date '1997-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'IRAN' order by  s_name ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'cornflower%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1997-01-01'      and l_shipdate < date '1997-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'MOROCCO' order by  s_name ;
SELECT l_linestatus FROM lineitem WHERE l_comment >= 'cajole carefully-- bold accounts nag blith' AND l_shipdate <= '1995-11-06' AND l_partkey <> 169433 AND l_suppkey <= 9174 AND l_tax > 0.05 AND l_linenumber >= 7
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#24'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 4 and l_quantity <= 4 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#43'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#45'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 26 and l_quantity <= 26 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select ps_availqty, l_returnflag, o_orderdate from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1995-09-02' AND l_partkey = 141608 AND l_receiptdate >= '1993-11-01' AND l_shipinstruct = 'NONE'
select l_suppkey, o_orderstatus from lineitem, orders where o_totalprice >= 80509.01 AND o_totalprice = 175867.34 AND l_extendedprice = 33655.6 AND l_linestatus = 'F'
select c_nationkey, o_custkey, n_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000060617' AND o_orderdate < '1996-03-27' AND o_comment = 'y final accounts. blithely stealthy foxes wake slyly. ironic excuses' order by c_nationkey ASC, n_regionkey DESC, r_name ASC
select c_nationkey, c_mktsegment, o_orderstatus from orders, customer, nation where o_totalprice < 139916.76 AND c_acctbal = 1481.44 AND c_name = 'Customer#000143733' AND c_mktsegment > 'BUILDING' AND o_shippriority < 0
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'metallic%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1993-01-01'      and l_shipdate < date '1993-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'IRAQ' order by  s_name ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%olive%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select ps_comment, l_partkey, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where p_retailprice = 1644.68 AND ps_comment = 'the quick excuses use daringly around the blithely pending packages. foxes use quickly. fluffily r' AND l_shipmode = 'SHIP' AND l_shipinstruct <= 'NONE'
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('15', '26', '28', '12', '31', '14', '13')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('15', '26', '28', '12', '31', '14', '13')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
SELECT n_regionkey, o_totalprice, c_acctbal, r_regionkey FROM orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey WHERE c_comment = 'kly regular orbits are. regular requests against the slyly ironic deposits na' AND c_name > 'Customer#000067979' AND n_comment <= 'pending excuses haggle furiously deposits. pending, express pinto beans wake fluffily past t'
SELECT n_name, s_comment, ps_supplycost, r_regionkey FROM region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey WHERE n_regionkey = 2 AND s_comment <= 'arefully regular requests. accounts nag furiously regular dependencies. carefu' AND n_comment <> 'ously. final, express gifts cajole a' ORDER BY ps_supplycost ASC, r_regionkey ASC, s_comment DESC, n_name DESC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('32', '17', '11', '33', '10', '21', '27')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('32', '17', '11', '33', '10', '21', '27')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select ps_availqty, l_returnflag, o_orderpriority from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1993-02-07' AND l_partkey = 141608 AND l_returnflag >= 'A' AND l_shipinstruct = 'NONE'
select  l_shipmode,  sum(case   when o_orderpriority = '1-URGENT'    or o_orderpriority = '2-HIGH'    then 1   else 0  end) as high_line_count,  sum(case   when o_orderpriority <> '1-URGENT'    and o_orderpriority <> '2-HIGH'    then 1   else 0  end) as low_line_count from  orders,  lineitem where  o_orderkey = l_orderkey  and l_shipmode in ('RAIL', 'TRUCK')  and l_commitdate < l_receiptdate  and l_shipdate < l_commitdate  and l_receiptdate >= date '1994-01-01'  and l_receiptdate < date '1994-01-01' + interval '1' year group by  l_shipmode order by  l_shipmode ;
select ps_comment, s_name, p_mfgr, r_comment, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where r_name < 'ASIA' AND ps_availqty = 8560 AND n_comment = 'ular asymptotes are about the furious multipliers. express dependencies nag above the ironically ironic account'
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1993-01-01'  and l_shipdate < date '1993-01-01' + interval '1' year  and l_discount between 0.03 - 0.01 and 0.03 + 0.01  and l_quantity < 24 ;
SELECT o_orderpriority, l_orderkey, SUM(o_orderkey) FROM orders JOIN lineitem ON l_orderkey = o_orderkey WHERE o_clerk = 'Clerk#000000957' AND o_orderkey < 5414343 AND l_receiptdate >= '1995-12-01' GROUP BY o_orderpriority, l_orderkey HAVING SUM(o_orderkey) >= 5765 ORDER BY o_orderpriority ASC
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'tan%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1993-01-01'      and l_shipdate < date '1993-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'INDONESIA' order by  s_name ;
SELECT l_tax, ps_comment FROM partsupp, lineitem WHERE l_discount <> 0.01 AND l_receiptdate >= '1996-02-15' AND l_suppkey = 1213 AND l_commitdate > '1998-03-21' AND l_shipmode < 'AIR' ORDER BY ps_comment ASC, l_tax ASC
SELECT c_name, o_orderdate, r_regionkey, n_comment FROM orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey WHERE c_acctbal >= 4329.02 AND r_comment <= 'lar deposits. blithely final packages cajole. regular waters are final requests. regular accounts are according to' AND o_orderdate < '1995-09-21' ORDER BY n_comment DESC
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 9934 AND s_comment < 'thes cajole above the ironic, regular accounts. regular, regular instructions use' AND ps_partkey <= 91752 AND s_nationkey < 17 AND s_acctbal > 4975.09 AND ps_supplycost <= 718.28
SELECT p_brand, l_receiptdate, ps_availqty FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey WHERE ps_supplycost > 996.79 AND l_partkey >= 106515 AND l_extendedprice < 27980.8 AND p_comment < 'lyly express de'
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 31  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  c_custkey,  c_name,  sum(l_extendedprice * (1 - l_discount)) as revenue,  c_acctbal,  n_name,  c_address,  c_phone,  c_comment from  customer,  orders,  lineitem,  nation where  c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate >= date '1994-02-01'  and o_orderdate < date '1994-02-01' + interval '3' month  and l_returnflag = 'R'  and c_nationkey = n_nationkey group by  c_custkey,  c_name,  c_acctbal,  c_phone,  n_name,  c_address,  c_comment order by  revenue desc limit 20;
select l_shipinstruct, ps_comment, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where l_partkey = 120307 AND ps_comment = 'he slyly even instructions. express, express ideas sleep slyly bold accounts. always final platelets are. instructions among the slyly even requests boost carefu' AND p_retailprice = 1831.73 AND l_shipmode <= 'MAIL'
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('13', '15', '31', '25', '27', '18', '29')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('13', '15', '31', '25', '27', '18', '29')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#22'  and p_container = 'SM JAR'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
SELECT s_name, ps_comment FROM supplier, partsupp WHERE s_suppkey < 3575 AND ps_suppkey <= 6112 AND s_acctbal >= 1647.97 AND s_phone = '15-284-495-3109' ORDER BY s_name DESC
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#33'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#14'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 13 and l_quantity <= 13 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#31'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 25 and l_quantity <= 25 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select o_totalprice, c_comment from customer JOIN orders ON o_custkey = c_custkey where c_mktsegment < 'AUTOMOBILE' AND o_orderdate = '1994-05-26' AND o_custkey < 9136 AND o_orderkey < 4400768
select l_shipinstruct, l_partkey, l_returnflag from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where o_orderdate > '1995-09-02' AND ps_availqty = 5830 AND o_orderpriority >= '2-HIGH' AND l_returnflag = 'A'
select l_comment, s_name, ps_partkey from supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey where l_shipinstruct = 'TAKE BACK RETURN' AND s_name = 'Supplier#000003443' AND s_suppkey = 1933 order by ps_partkey DESC, s_name ASC
select  o_year,  sum(case   when nation = 'MOROCCO' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AFRICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'MEDIUM POLISHED COPPER'  ) as all_nations group by  o_year order by  o_year ;
select s_name, ps_comment, n_comment, r_comment, n_name from region JOIN nation ON n_regionkey = r_regionkey JOIN supplier ON s_nationkey = n_nationkey JOIN partsupp ON ps_suppkey = s_suppkey JOIN part ON p_partkey = ps_partkey where r_name < 'AMERICA' AND ps_availqty = 8560 AND p_mfgr = 'Manufacturer#4'
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 3  and p_type like '%COPPER'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AFRICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AFRICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select p_retailprice, ps_supplycost, max(p_retailprice) from part JOIN partsupp ON ps_partkey = p_partkey where p_mfgr = 'Manufacturer#1' AND p_mfgr = 'Manufacturer#4' AND ps_partkey <= 180166 group by ps_supplycost, p_retailprice having max(p_retailprice) = 1815.88
SELECT s_nationkey, ps_comment, MIN(ps_partkey) FROM partsupp, supplier WHERE ps_suppkey = 5171 AND ps_comment <= 'l theodolites across the slyly unusual accounts wake carefully pending accounts' AND s_suppkey <= 4974 GROUP BY s_nationkey, ps_comment HAVING MIN(ps_partkey) <= 49795 ORDER BY s_nationkey ASC, ps_comment DESC
select  cntrycode,  count(*) as numcust,  sum(c_acctbal) as totacctbal from  (   select    substring(c_phone from 1 for 2) as cntrycode,    c_acctbal   from    customer   where    substring(c_phone from 1 for 2) in     ('10', '22', '19', '31', '25', '29', '32')    and c_acctbal > (     select      avg(c_acctbal)     from      customer     where      c_acctbal > 0.00      and substring(c_phone from 1 for 2) in       ('10', '22', '19', '31', '25', '29', '32')    )    and not exists (     select      *     from      orders     where      o_custkey = c_custkey    )  ) as custsale group by  cntrycode order by  cntrycode ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'bisque%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1996-01-01'      and l_shipdate < date '1996-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'IRAN' order by  s_name ;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 16  and p_type like '%NICKEL'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'ASIA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'ASIA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  s_name,  count(*) as numwait from  supplier,  lineitem l1,  orders,  nation where  s_suppkey = l1.l_suppkey  and o_orderkey = l1.l_orderkey  and o_orderstatus = 'F'  and l1.l_receiptdate > l1.l_commitdate  and exists (   select    *   from    lineitem l2   where    l2.l_orderkey = l1.l_orderkey    and l2.l_suppkey <> l1.l_suppkey  )  and not exists (   select    *   from    lineitem l3   where    l3.l_orderkey = l1.l_orderkey    and l3.l_suppkey <> l1.l_suppkey    and l3.l_receiptdate > l3.l_commitdate  )  and s_nationkey = n_nationkey  and n_name = 'GERMANY' group by  s_name order by  numwait desc,  s_name limit 100;
select  o_orderpriority,  count(*) as order_count from  orders where  o_orderdate >= date '1997-03-01'  and o_orderdate < date '1997-03-01' + interval '3' month  and exists (   select    *   from    lineitem   where    l_orderkey = o_orderkey    and l_commitdate < l_receiptdate  ) group by  o_orderpriority order by  o_orderpriority ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%azure%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#14'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#35'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 11 and l_quantity <= 11 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 26 and l_quantity <= 26 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select  ps_partkey,  sum(ps_supplycost * ps_availqty) as value from  partsupp,  supplier,  nation where  ps_suppkey = s_suppkey  and s_nationkey = n_nationkey  and n_name = 'MOZAMBIQUE' group by  ps_partkey having   sum(ps_supplycost * ps_availqty) > (    select     sum(ps_supplycost * ps_availqty) * 0.0001000000    from     partsupp,     supplier,     nation    where     ps_suppkey = s_suppkey     and s_nationkey = n_nationkey     and n_name = 'MOZAMBIQUE'   ) order by  value desc ;
SELECT l_shipmode, n_nationkey, ps_suppkey, s_name FROM lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey WHERE s_suppkey > 3575 AND ps_comment > 'ular requests boost pinto beans. even, regular deposits cajole according to the regular foxes. even deposits according to the bravely daring requests print caref' AND s_phone >= '24-914-931-3627'
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'GERMANY' and n2.n_name = 'INDIA')     or (n1.n_name = 'INDIA' and n2.n_name = 'GERMANY')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  sum(l_extendedprice * l_discount) as revenue from  lineitem where  l_shipdate >= date '1995-01-01'  and l_shipdate < date '1995-01-01' + interval '1' year  and l_discount between 0.09 - 0.01 and 0.09 + 0.01  and l_quantity < 25 ;
select  s_name,  count(*) as numwait from  supplier,  lineitem l1,  orders,  nation where  s_suppkey = l1.l_suppkey  and o_orderkey = l1.l_orderkey  and o_orderstatus = 'F'  and l1.l_receiptdate > l1.l_commitdate  and exists (   select    *   from    lineitem l2   where    l2.l_orderkey = l1.l_orderkey    and l2.l_suppkey <> l1.l_suppkey  )  and not exists (   select    *   from    lineitem l3   where    l3.l_orderkey = l1.l_orderkey    and l3.l_suppkey <> l1.l_suppkey    and l3.l_receiptdate > l3.l_commitdate  )  and s_nationkey = n_nationkey  and n_name = 'EGYPT' group by  s_name order by  numwait desc,  s_name limit 100;
select o_shippriority, o_totalprice from lineitem, orders where o_orderpriority > '3-MEDIUM' AND o_orderstatus = 'O' AND l_suppkey = 8624 AND l_extendedprice = 28681.83
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#34'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 1 and l_quantity <= 1 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#55'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 13 and l_quantity <= 13 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#24'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 22 and l_quantity <= 22 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select l_linestatus, l_commitdate from lineitem, partsupp where l_tax = 0.04 AND l_orderkey < 768929 AND l_extendedprice < 7455.28 AND ps_availqty = 1078
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 30  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 17  and p_type like '%COPPER'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'EUROPE'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'EUROPE'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  l_returnflag,  l_linestatus,  sum(l_quantity) as sum_qty,  sum(l_extendedprice) as sum_base_price,  sum(l_extendedprice * (1 - l_discount)) as sum_disc_price,  sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,  avg(l_quantity) as avg_qty,  avg(l_extendedprice) as avg_price,  avg(l_discount) as avg_disc,  count(*) as count_order from  lineitem where  l_shipdate <= date '1998-12-01' - interval '94' day group by  l_returnflag,  l_linestatus order by  l_returnflag,  l_linestatus ;
SELECT c_mktsegment, l_suppkey, ps_availqty, o_clerk FROM customer JOIN orders ON o_custkey = c_custkey JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey WHERE c_comment <> 'ly express packages are about the quickly bold foxes. final dependencies after the quickly idle acco' AND l_receiptdate < '1995-10-09' AND l_commitdate < '1997-08-12' AND l_linenumber < 1 AND ps_comment < 'nts. bold, final theodolites wake after the regular Tiresias. blithely dogged requests are slyly according to the pending, stealt' ORDER BY c_mktsegment DESC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#25'  and p_type not like 'PROMO ANODIZED%'  and p_size in (37, 25, 8, 47, 17, 9, 49, 6)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%indian%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'tan%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1996-01-01'      and l_shipdate < date '1996-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'ARGENTINA' order by  s_name ;
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%orchid%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select  sum(l_extendedprice* (1 - l_discount)) as revenue from  lineitem,  part where  (   p_partkey = l_partkey   and p_brand = 'Brand#25'   and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')   and l_quantity >= 7 and l_quantity <= 7 + 10   and p_size between 1 and 5   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#11'   and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')   and l_quantity >= 10 and l_quantity <= 10 + 10   and p_size between 1 and 10   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  )  or  (   p_partkey = l_partkey   and p_brand = 'Brand#23'   and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')   and l_quantity >= 20 and l_quantity <= 20 + 10   and p_size between 1 and 15   and l_shipmode in ('AIR', 'AIR REG')   and l_shipinstruct = 'DELIVER IN PERSON'  ) ;
select c_nationkey, o_custkey, n_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000113662' AND o_orderdate < '1995-01-28' AND o_comment = 'ncies. fluffily regular accounts sleep about the foxes. quietly unusual' order by c_nationkey ASC, n_regionkey DESC, r_name ASC
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 45  and p_type like '%COPPER'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'AMERICA'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'AMERICA'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  s_acctbal,  s_name,  n_name,  p_partkey,  p_mfgr,  s_address,  s_phone,  s_comment from  part,  supplier,  partsupp,  nation,  region where  p_partkey = ps_partkey  and s_suppkey = ps_suppkey  and p_size = 35  and p_type like '%TIN'  and s_nationkey = n_nationkey  and n_regionkey = r_regionkey  and r_name = 'MIDDLE EAST'  and ps_supplycost = (   select    min(ps_supplycost)   from    partsupp,    supplier,    nation,    region   where    p_partkey = ps_partkey    and s_suppkey = ps_suppkey    and s_nationkey = n_nationkey    and n_regionkey = r_regionkey    and r_name = 'MIDDLE EAST'  ) order by  s_acctbal desc,  n_name,  s_name,  p_partkey limit 100;
select  l_orderkey,  sum(l_extendedprice * (1 - l_discount)) as revenue,  o_orderdate,  o_shippriority from  customer,  orders,  lineitem where  c_mktsegment = 'AUTOMOBILE'  and c_custkey = o_custkey  and l_orderkey = o_orderkey  and o_orderdate < date '1995-03-23'  and l_shipdate > date '1995-03-23' group by  l_orderkey,  o_orderdate,  o_shippriority order by  revenue desc,  o_orderdate limit 10;
select s_nationkey, ps_supplycost from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 1268 AND s_comment < 'about the silently quiet deposits. quickly e' AND ps_partkey <= 173618 AND s_nationkey < 17 AND s_acctbal > 6305.29 AND ps_supplycost <= 628.53
SELECT o_comment FROM orders WHERE o_comment <= 'carefully about the unusual requ' AND o_clerk <= 'Clerk#000000649' AND o_totalprice < 130861.55 AND o_orderpriority >= '3-MEDIUM' AND o_orderstatus <= 'F' AND o_shippriority <= 0 ORDER BY o_comment DESC
SELECT l_comment, s_name, ps_partkey FROM supplier JOIN partsupp ON ps_suppkey = s_suppkey JOIN lineitem ON l_suppkey = ps_suppkey WHERE l_shipinstruct <> 'NONE' AND s_name = 'Supplier#000000551' AND s_suppkey <> 1933 ORDER BY ps_partkey DESC, s_name ASC
select  s_name,  s_address from  supplier,  nation where  s_suppkey in (   select    ps_suppkey   from    partsupp   where    ps_partkey in (     select      p_partkey     from      part     where      p_name like 'red%'    )    and ps_availqty > (     select      0.5 * sum(l_quantity)     from      lineitem     where      l_partkey = ps_partkey      and l_suppkey = ps_suppkey      and l_shipdate >= date '1997-01-01'      and l_shipdate < date '1997-01-01' + interval '1' year    )  )  and s_nationkey = n_nationkey  and n_name = 'UNITED STATES' order by  s_name ;
select l_commitdate, ps_availqty from lineitem, partsupp where l_linestatus = 'O' AND l_orderkey < 4758179 AND l_tax < 0.07 AND l_extendedprice = 72229.68
select ps_availqty, l_partkey, o_orderdate from orders JOIN lineitem ON l_orderkey = o_orderkey JOIN partsupp ON ps_suppkey = l_suppkey where l_shipinstruct > 'NONE' AND o_orderpriority = '2-HIGH' AND l_returnflag >= 'N' AND l_returnflag = 'N'
select  100.00 * sum(case   when p_type like 'PROMO%'    then l_extendedprice * (1 - l_discount)   else 0  end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue from  lineitem,  part where  l_partkey = p_partkey  and l_shipdate >= date '1993-10-01'  and l_shipdate < date '1993-10-01' + interval '1' month ;
select  o_year,  sum(case   when nation = 'INDIA' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'ASIA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'STANDARD ANODIZED NICKEL'  ) as all_nations group by  o_year order by  o_year ;
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#21'  and p_type not like 'ECONOMY POLISHED%'  and p_size in (7, 42, 20, 12, 44, 37, 9, 15)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'O' AND p_size = 1 AND l_commitdate <= '1998-10-10' AND ps_supplycost < 181.68 AND ps_comment > 'ronic dolphins must wake slyly ruthlessly bold ideas. furiously even requests across the quickly ironic in' order by ps_partkey DESC, p_name ASC
select l_receiptdate, l_suppkey from orders, lineitem where o_orderpriority >= '5-LOW' AND o_totalprice = 168844.46 AND o_custkey > 71746 AND l_tax > 0.02 order by l_receiptdate DESC, l_suppkey ASC
select  supp_nation,  cust_nation,  l_year,  sum(volume) as revenue from  (   select    n1.n_name as supp_nation,    n2.n_name as cust_nation,    extract(year from l_shipdate) as l_year,    l_extendedprice * (1 - l_discount) as volume   from    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2   where    s_suppkey = l_suppkey    and o_orderkey = l_orderkey    and c_custkey = o_custkey    and s_nationkey = n1.n_nationkey    and c_nationkey = n2.n_nationkey    and (     (n1.n_name = 'MOZAMBIQUE' and n2.n_name = 'GERMANY')     or (n1.n_name = 'GERMANY' and n2.n_name = 'MOZAMBIQUE')    )    and l_shipdate between date '1995-01-01' and date '1996-12-31'  ) as shipping group by  supp_nation,  cust_nation,  l_year order by  supp_nation,  cust_nation,  l_year ;
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#25'  and p_container = 'LG JAR'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select s_suppkey, ps_availqty, n_nationkey from partsupp JOIN supplier ON s_suppkey = ps_suppkey JOIN nation ON n_nationkey = s_nationkey where n_regionkey < 0 AND n_comment >= 'hely enticingly express accounts. even, final' AND ps_availqty >= 9419 order by ps_availqty ASC
select  nation,  o_year,  sum(amount) as sum_profit from  (   select    n_name as nation,    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity as amount   from    part,    supplier,    lineitem,    partsupp,    orders,    nation   where    s_suppkey = l_suppkey    and ps_suppkey = l_suppkey    and ps_partkey = l_partkey    and p_partkey = l_partkey    and o_orderkey = l_orderkey    and s_nationkey = n_nationkey    and p_name like '%sky%'  ) as profit group by  nation,  o_year order by  nation,  o_year desc ;
select ps_supplycost, ps_partkey from partsupp JOIN supplier ON s_suppkey = ps_suppkey where ps_availqty >= 9048 AND s_acctbal < 897.14 AND s_nationkey <= 13 AND s_nationkey < 17 AND ps_supplycost > 57.43 AND s_comment <= 'quests could use furiously across the ironic, even f'
select o_custkey from orders where o_clerk = 'Clerk#000000951' AND o_orderstatus <= 'O' AND o_shippriority >= 0 AND o_orderkey = 1472992 order by o_custkey ASC
select  p_brand,  p_type,  p_size,  count(distinct ps_suppkey) as supplier_cnt from  partsupp,  part where  p_partkey = ps_partkey  and p_brand <> 'Brand#54'  and p_type not like 'MEDIUM PLATED%'  and p_size in (8, 41, 19, 17, 29, 6, 26, 18)  and ps_suppkey not in (   select    s_suppkey   from    supplier   where    s_comment like '%Customer%Complaints%'  ) group by  p_brand,  p_type,  p_size order by  supplier_cnt desc,  p_brand,  p_type,  p_size ;
select c_nationkey, o_custkey, n_regionkey, r_name from orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey where c_name = 'Customer#000116589' AND o_orderdate < '1995-01-28' AND o_comment = 'ggle. carefully ironic ideas' order by o_custkey ASC, n_regionkey DESC, r_name ASC
select  o_year,  sum(case   when nation = 'MOROCCO' then volume   else 0  end) / sum(volume) as mkt_share from  (   select    extract(year from o_orderdate) as o_year,    l_extendedprice * (1 - l_discount) as volume,    n2.n_name as nation   from    part,    supplier,    lineitem,    orders,    customer,    nation n1,    nation n2,    region   where    p_partkey = l_partkey    and s_suppkey = l_suppkey    and l_orderkey = o_orderkey    and o_custkey = c_custkey    and c_nationkey = n1.n_nationkey    and n1.n_regionkey = r_regionkey    and r_name = 'AFRICA'    and s_nationkey = n2.n_nationkey    and o_orderdate between date '1995-01-01' and date '1996-12-31'    and p_type = 'STANDARD ANODIZED TIN'  ) as all_nations group by  o_year order by  o_year ;
select l_shipmode, ps_partkey, s_name, min(s_name), sum(ps_partkey) from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN supplier ON s_suppkey = ps_suppkey where s_comment = 'ic requests nag. blithely regular ideas try to wake quickly eve' AND l_partkey < 179531 AND s_phone > '25-585-189-5975' group by l_shipmode, ps_partkey, s_name having min(s_name) <= 'Supplier#000006418' order by sum(ps_partkey) DESC, min(s_name) ASC
SELECT o_totalprice, c_acctbal, n_name, r_comment FROM orders JOIN customer ON c_custkey = o_custkey JOIN nation ON n_nationkey = c_nationkey JOIN region ON r_regionkey = n_regionkey WHERE c_nationkey >= 24 AND n_regionkey <> 0 AND n_nationkey <= 6 ORDER BY c_acctbal ASC, n_name ASC, r_comment DESC, o_totalprice DESC
SELECT ps_supplycost, p_partkey FROM partsupp, part WHERE p_size <> 10 AND ps_availqty = 7950 AND ps_supplycost >= 883.81 AND p_brand <> 'Brand#52' ORDER BY p_partkey ASC
select  sum(l_extendedprice) / 7.0 as avg_yearly from  lineitem,  part where  p_partkey = l_partkey  and p_brand = 'Brand#34'  and p_container = 'LG DRUM'  and l_quantity < (   select    0.2 * avg(l_quantity)   from    lineitem   where    l_partkey = p_partkey  ) ;
select l_orderkey, p_name, ps_partkey from part JOIN partsupp ON ps_partkey = p_partkey JOIN lineitem ON l_suppkey = ps_suppkey where l_linestatus = 'O' AND p_type = 'LARGE ANODIZED BRASS' AND l_commitdate = '1993-06-14' AND l_orderkey < 3692354 AND ps_comment > 'fully even ideas. blithely express accounts thrash blithely regular pinto beans. packages need to unwind pending excuses. final packages after the packages are furiously silently final co' order by ps_partkey DESC, p_name ASC
select ps_comment, l_partkey, p_comment from lineitem JOIN partsupp ON ps_suppkey = l_suppkey JOIN part ON p_partkey = ps_partkey where ps_comment = 'ions. express, even requests cajole carefully. silent foxes wake. blithely ironic pinto beans boost quickly regular instructions. fluffily pending dependencies are alongside of the pinto beans.' AND l_shipmode = 'AIR' AND l_shipinstruct = 'NONE' AND p_retailprice <= 1831.73
